INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(8, 'koKR', 'Łotrowski interes', 'Hej, $gkolego:koleżanko;! Wyświadczysz przysługę młodemu chłopakowi, który natłukł się już bezmyślnych zombie i pająków więcej, niż mu się należało?$B$BMam tu list, który musi trafić do Brill... do karczmarki, Renee jakiejśtam. Nieważne, jak ona ma na nazwisko.$B$BW każdym razie to miłe, przytulne miejsce, pełne ofiar zarazy, które próbują jakoś się urządzić na tym świecie. Świetne też, żeby odpocząć, gdyby zaszła potrzeba. Zajrzyj tam... zrobisz to, a dobrze ci zapłacę.', 'Dostarcz niepozorny list karczmarce Renee na Polanach Tirisfal.', '', '', '', '', '', '', 0),
(105, 'koKR', 'Ach, Andorhal', 'Oto nadszedł czas, by uderzyć na Andorhal i przepędzić lisza, który nim włada!$B$BW ruinach miasta panuje lisz Araj Przywoływacz. Strzegą go liczne zastępy Plagi otaczające pozostałości centrum miasta, a jego osobista świta strażników jest groźna. Będziesz potrzebować wielu sojuszników, by w ogóle mieć szansę go pokonać.$B$BZniszcz Araja, $N, i przynieś mi odłamek jego filakterii jako dowód!', 'Przynieś odłamek filakterii Araja najwyższemu egzekutorowi Derringtonowi na Barykadzie na Zachodnich Plagowiskach.', '', 'Wróć do najwyższego egzekutora Derringtona na Barykadzie na Polanach Tirisfal.', '', '', '', '', 0),
(211, 'koKR', 'Ach, Andorhal', 'Oto nadszedł czas, by uderzyć na Andorhal i przepędzić lisza, który nim włada!$B$BW ruinach miasta panuje lisz Araj Przywoływacz. Strzegą go liczne zastępy Plagi otaczające pozostałości centrum miasta, a jego osobista świta strażników jest groźna. Będziesz potrzebować wielu sojuszników, by w ogóle mieć szansę go pokonać.$B$BZniszcz Araja, $N, i przynieś mi odłamek jego filakterii jako dowód!', 'Przynieś odłamek filakterii Araja dowódcy Ashlamowi Mężnopięściowi do Obozu Zimnych Wichrów na Zachodnich Plagowiskach.', '', 'Wróć do dowódcy Ashlama Mężnopięścia w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', 0),
(354, 'koKR', 'Śmierć w rodzinie', 'Agamandowie byli najzamożniejszą rodziną na Polanach Tirisfal. Pracowałem w ich młynach... przed zarazą.$B$BGdy nadeszła Plaga, Agamandowie ufortyfikowali swój dom i przekonali tych, którzy u nich służyli, by zostali i pomogli w obronie. Byliśmy głupcami, ale przynajmniej lojalnymi głupcami.$B$BAgamandowie w swojej pysze skazali nas na nieżycie. A teraz sami są sługami Plagi!$B$BPrzysłuż się Porzuconym i pokonaj Agamandów, którzy padli ofiarą zarazy. A mnie przysłużysz się, przynosząc ich szczątki.', 'Przynieś szczątki Gregora, szczątki Nissy i szczątki Thurmana Colemanowi Farthingowi w Brill.', '', 'Wróć do Colemana Farthinga w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(355, 'koKR', 'Porozmawiaj z Sevrenem', '$GPrzyniosłeś:Przyniosłaś; mi szczątki Agamandów i $gzaspokoiłeś:zaspokoiłaś; moje pragnienie zemsty. Ale Młynówka Agamandów zagraża wszystkim Porzuconym, nie tylko mnie.$B$BOpowiedziałem sędziemu Sevrenowi o twoich wyczynach przeciw Agamandom i chce z tobą porozmawiać.', 'Porozmawiaj z sędzią Sevrenem w Brill.', '', '', '', '', '', '', 0),
(356, 'koKR', 'Patrol na tyłach', 'Obrońcy Barykady, którzy chronią Tirisfal przed Plagowiskami, są w ciągłej gotowości. Ale czasem Plaga przemyka się obok nich.$B$BNasz sukces na Barykadzie zależy od walki na jednym froncie – nie możemy dopuścić do ataku od tyłu ani do przecięcia linii zaopatrzenia naszych obrońców.$B$BWesprzyj Barykadę. Patroluj tereny na wschodzie i zabijaj każdego sługę Plagi, jakiego napotkasz. Szczególnie przyłóż się w Gospodarstwie Balnira na wschodzie. Stało się przystanią dla intruzów z Plagi.', 'Zabij 8 krwawiących potworów i 8 wędrujących duchów, a następnie złóż raport Linnei w jej obozie.', '', 'Wróć do strażniczki śmierci Linnei na Polanach Tirisfal.', '', '', '', '', 0),
(358, 'koKR', 'Hieny cmentarne', 'Zbiorowe Mogiły, na południowy zachód od Nawiedziska Garrena na północy, wykopano, by pomieścić... imponującą... liczbę zmarłych, jaką zbierała zaraza w Tirisfal, kiedy tu nadeszła.$B$BCiała w tych grobach jak dotąd uniknęły nieżycia, ale Plaga wysyła teraz gnole ze Zgniłofutrych, by zbierały zwłoki i zasilały nimi jej armie. Nie można na to pozwolić!$B$BTwoje zadanie jest dwojakie: zabijaj Zgniłofutrych przy Zbiorowych Mogiłach i w Nawiedzisku Garrena i zbierz od nich posokę do balsamowania, która daje im życie.', 'Zabij hieny cmentarne ze Zgniłofutrych i kundle ze Zgniłofutrych.$B$BPrzynieś 8 porcji posoki do balsamowania sędziemu Sevrenowi w Brill.', '', 'Wróć do sędziego Sevrena w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(359, 'koKR', 'Obowiązki Porzuconych', 'Potrzebuję świeżego raportu z naszego posterunku strażników śmierci na wschodzie.$B$BMuszę wiedzieć, czy kolejne siły Plagi prześlizgnęły się obok Barykady do Tirisfal. Musimy zachować czujność na granicy z Plagowiskami – nie możemy pozwolić, by Plaga zyskała tu mocniejszy przyczółek!$B$BIdź drogą na południe, a na rozwidleniu skręć na wschód, do posterunku. Porozmawiaj ze strażniczką śmierci Linneą. Ma informacje, których potrzebuję.', 'Porozmawiaj ze strażniczką śmierci Linneą.', '', '', '', '', '', '', 0),
(360, 'koKR', 'Powrót do sędziego', 'Teraz wróć do sędziego Sevrena z informacjami, które ci przekazałam. Będzie ich potrzebował jak najszybciej, więc się pospiesz.$B$BA jeśli po drodze napotkasz sługi Plagi, zniszcz je – nie możemy pozwolić, by bezkarnie włóczyły się po naszych ziemiach.', 'Wróć do sędziego Sevrena w Brill.', '', '', '', '', '', '', 0),
(361, 'koKR', 'Niedoręczony list', 'To list napisany przez Thurmana, starszego syna Gregora Agamanda. Jest zaadresowany do niejakiej Yvette Farthing, ale wygląda na to, że nigdy do niej nie dotarł...', 'Odnajdź Yvette Farthing i doręcz jej list od Thurmana Agamanda.', '', '', '', '', '', '', 0),
(362, 'koKR', 'Nawiedzone młyny', 'Devlin Agamand był młodszym z dwóch synów Agamandów, a za życia bracia nie mogli bardziej się różnić. Thurman był wysoki i łagodny, a jego młodszy brat – słaby i cięty w mowie.$B$BGdy Młynówka Agamandów padła ofiarą zarazy, nie zdziwiłem się, słysząc, że Devlin szybko uległ. Jego obłąkany bełkot wciąż słychać przy drodze prowadzącej do Młynówki Agamandów.$B$BZbieram szczątki Agamandów i chcę mieć biednego Devlina. Znajdź go, zniszcz i przynieś mi jego kości.', 'Zabij Devlina Agamanda i przynieś szczątki Devlina Colemanowi Farthingowi w Brill.', '', 'Wróć do Colemana Farthinga w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(363, 'koKR', 'Brutalne przebudzenie', 'Najwyższy czas, że się $gobudziłeś:obudziłaś;. Już mieliśmy cię wrzucić do ognia z resztą, ale wygląda na to, że ci się udało.$b$bJestem Mordo, dozorca krypty w Podzwonnem. A ty nie jesteś już $gniewolnikiem:niewolnicą; Króla Lisza.$b$bPorozmawiaj z kapłanem cienia Sarvisem w kaplicy u stóp wzgórza. Powie ci więcej o tym, co musisz wiedzieć.$B$BŻeby wyjść z krypty, wejdź po schodach na powierzchnię. Idź drogą w dół do kaplicy, tam znajdziesz Sarvisa.', 'Porozmawiaj z kapłanem cienia Sarvisem.', '', '', '', '', '', '', 0),
(364, 'koKR', 'Bezmyślni', 'My, Porzuceni, toczymy wojnę z armią Plagi Króla Lisza: z nekromantycznie wskrzeszonymi zastępami nieumarłych, plugawymi bestiami północy i udręczonymi upiorami.$b$bPółnocną część wioski opanowali Bezmyślni i trzeba ich zniszczyć. Niszcz ich bez litości, choćby byli naszymi dawnymi braćmi i siostrami. Upadli to tylko niewolnicy Króla Lisza.', 'Kapłan cienia Sarvis chce, żebyś $gzabił:zabiła; 5 bezmyślnych zombie i 5 nędznych ghuli.', '', 'Wróć do kapłana cienia Sarvisa w Podzwonnem na Polanach Tirisfal.', '', '', '', '', 0),
(365, 'koKR', 'Pola żałoby', 'Co my tu mamy? Wyglądasz na $gżółtodzioba:żółtodziobkę;. Jeśli chcesz się wykazać przed Mroczną Panią, musisz poznać obyczaje Porzuconych.$b$bNa zachodzie znajdziesz farmę. Ludzie obłażą tę ziemię jak pleśń gnijące zwłoki. Co gorsza, w pobliżu patroluje Szkarłatna Krucjata ze swojej wieży. Daj tym szumowinom nauczkę i ukradnij 10 ich cennych dyń.$b$bGdy zbierzesz 10, zanieś je aptekarzowi Johaanowi w Brill.', 'Ukradnij 10 dyń z farmy na zachodzie, tuż na północ od Podzwonnego, i zanieś je aptekarzowi Johaanowi w Brill.', '', 'Wróć do aptekarza Johaana w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(366, 'koKR', 'Zwróć księgę', 'Dawno temu Gunther i ja, a także Thule Kruczy Szpon – dziś nekromanta Plagi – byliśmy przyjaciółmi i uczniami w Kirin Torze, stowarzyszeniu magów z Dalaranu.$B$BGunther i ja padliśmy ofiarą zarazy, ale sądziłem, że albo pozostał martwy, albo wskrzeszono go w szeregi Króla Lisza. Dobrze wiedzieć, że jest wolny.$B$BMusimy go pozyskać. Rzuciłem na jego księgę zaklęcie, które, gdy ją zobaczy, pokaże mu, że i ja jestem wolny od Króla Lisza. Mam nadzieję, że gdy się o tym dowie, dołączy do nas.', 'Oddaj Guntherowi jego księgę zaklęć w Ustroniu Gunthera, na wyspie.', '', '', '', '', '', '', 0),
(367, 'koKR', 'Nowa zaraza', 'Lady Sylwana wezwała Królewskie Zakłady Chemiczne. Mroczna Pani wierzy, że nasza wiedza w połączeniu z nowo odkrytą magią okaże się kluczem do upadku Arthasa. Rzuciła nam wyzwanie: mamy stworzyć nową zarazę, groźniejszą niż jakakolwiek choroba w Azeroth. Ta nowa choroba doprowadzi armię Plagi Arthasa do zguby.$b$bMoje badania wskazują, że kluczem może być krew bestii. Przynieś mi 5 fiolek krwi mrocznych ogarów, żebym mógł sprawdzić swoją teorię.', 'Aptekarz Johaan z Brill chce, żebyś $gzebrał:zebrała; 5 fiolek krwi mrocznego ogara.', '', 'Wróć do aptekarza Johaana w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(368, 'koKR', 'Nowa zaraza', 'Gdy $gzbierałeś:zbierałaś; dla mnie próbki, moje eksperymenty uświadomiły mi, że do właściwego rozprzestrzenienia się tej nowej choroby potrzeba więcej odczynników. Otrucie jakiejś nieszczęsnej ofiary to dziecinna igraszka. Zarażenie całego świata okazuje się nieco bardziej skomplikowane.$b$bBędę potrzebował 5 łusek Plugawopłetwych od murloków z okolicy. Znajdziesz te stwory na wybrzeżu na północy lub na zachodzie.', 'Aptekarz Johaan z Brill potrzebuje 5 łusek Plugawopłetwych od murloków z Polan Tirisfal.', '', 'Wróć do aptekarza Johaana w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(369, 'koKR', 'Nowa zaraza', 'Gdy $gbyłeś:byłaś; w terenie, znalazłem w jednej z moich ksiąg stary tekst, z którego wynika, że pradawna zaraza zgładziła tysiące niewinnych ofiar. Później odkryto, że zabójczy czynnik tej zarazy przetrwał w jadzie pająków Nocnej Sieci.$b$bPrzynieś mi trochę jadu okrutnego pająka Nocnej Sieci, żebym mógł dokończyć ten eksperyment. Chcę sprawdzić, czy zakaźny składnik jadu zadziała z moją nową miksturą. Podobno te pająki można znaleźć we wschodniej części Polan Tirisfal.', 'Aptekarz Johaan z Brill chce, żebyś $gprzyniósł:przyniosła; mu 4 próbki jadu okrutnego pająka Nocnej Sieci.', '', 'Wróć do aptekarza Johaana w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(370, 'koKR', 'Wojna ze Szkarłatną Krucjatą', 'Dokumenty strategiczne od egzekutora Arrena zawierają wszystko, czego potrzebujemy, by wytępić z tych ziem ludzką zarazę. Według nich Szkarłatna Krucjata wysłała kapitana Perrine\'a z brygadą do zrujnowanej wieży na południowy zachód od Brill.$b$bZabij Perrine\'a oraz 3 fanatyków i 3 misjonarzy, a potem złóż mi raport.', 'Egzekutor Zygand w Brill chce, żebyś $gzabił:zabiła; kapitana Perrine\'a, 3 szkarłatnych fanatyków i 3 szkarłatnych misjonarzy.', '', 'Wróć do egzekutora Zyganda w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(371, 'koKR', 'Wojna ze Szkarłatną Krucjatą', 'Wojna trwa, a Szkarłatna Krucjata rośnie w siłę. Z raportu egzekutora Arrena wynika, że szkarłatni krzyżowcy pod dowództwem kapitana Vachona urządzają wypady ze zrujnowanej wieży w południowo-wschodnim Tirisfal, w pobliżu Gospodarstwa Balnira.$b$bZabij Vachona oraz 5 szkarłatnych zakonników. To powinien być druzgocący cios dla Krucjaty!', 'Egzekutor Zygand w Brill zlecił ci zabicie kapitana Vachona i 5 szkarłatnych zakonników.', '', 'Wróć do egzekutora Zyganda w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(372, 'koKR', 'Wojna ze Szkarłatną Krucjatą', 'Szkarłatni krzyżowcy urządzają wypady ze zrujnowanej wieży w północnym Tirisfal, za Spoczynkiem Faola. Według naszych informacji tą podłą bandą dowodzi bezwzględny kapitan Melrache.$b$bPowierzam ci teraz specjalną i niebezpieczną misję. Zabij Melrache\'a i jego dwóch ochroniarzy w imię Mrocznej Pani.', 'Egzekutor Zygand z Brill chce, żebyś $gzgładził:zgładziła; kapitana Melrache\'a i jego dwóch ochroniarzy.', '', 'Wróć do egzekutora Zyganda w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(374, 'koKR', 'Dowód zgonu', 'Egzekutor Zygand mówi, że $gzabijałeś:zabijałaś; szkarłatnych krzyżowców. Polany Tirisfal aż się od nich roją.$b$bVarimathras, zastępca Mrocznej Pani, osobiście dba o to, by szumowiny Azeroth, rasa ludzka, zostały zmiecione w niebyt. Tu, na Polanach Tirisfal, mamy do czynienia ze szczególnie uciążliwą odmianą ludzi: Szkarłatną Krucjatą.$b$bWyrusz i uderz na Szkarłatną Krucjatę, $N. Przynieś mi 10 pierścieni ze szkarłatnym insygnium jako dowód swojej lojalności wobec Varimathrasa i Mrocznej Pani.', 'Przynieś 10 pierścieni ze szkarłatnym insygnium strażnikowi śmierci Burgessowi w Brill.', '', 'Wróć do strażnika śmierci Burgessa w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(375, 'koKR', 'Chłód śmierci', 'Tak teraz zimno. Zaraza nieżycia pełznie mi po żyłach jak lodowaty wąż. Wkrótce dopadnie mnie Bezmyślność. Ale żadne przeklęte przeznaczenie nie powstrzyma mnie przed służbą naszej Mrocznej Pani. Gdy padło wezwanie, szyłam worki na ciała poległych żołnierzy potężnej armii Sylwany.$b$bTeraz ręce trzęsą mi się z zimna. Gdybyś $gprzyniósł:przyniosła; mi pięć skór zmierzchtoperzy i trochę grubej nici, mogłabym uszyć sobie koc. Pomóż mi, $N, żebym mogła dalej służyć sprawie.', 'Przynieś pięć skór zmierzchtoperzy i trochę grubej nici Gretchen Dedmar w Brill.', '', 'Wróć do Gretchen Dedmar w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(376, 'koKR', 'Potępieni', 'Do moich obowiązków należy opieka nad rannymi wojownikami, szycie pancerzy i ubrań oraz pomoc kapłanowi cienia Sarvisowi we wszystkim, czego jeszcze potrzebuje.$b$bWygląda na to, że i ty trafisz do niego na służbę... do polowania na Bezmyślnych, jeśli dobrze go znam. Cóż, jeśli chcesz zostać w jednym kawałku – a nie wątpię, że chcesz – mogę ci pomóc. Kończą mi się łapy i skrzydła, więc jeśli mi je przyniesiesz, znajdę dla ciebie jakiś pancerz. Sporo wilków i nietoperzy znajdziesz na południu.', 'Nowicjuszka Elreth potrzebuje 6 łap padlinożerców i 6 skrzydeł zmierzchtoperzy.', '', 'Wróć do nowicjuszki Elreth w Podzwonnem na Polanach Tirisfal.', '', '', '', '', 0),
(380, 'koKR', 'Kotlina Nocnej Sieci', 'Jednym z naszych największych problemów jest zdobywanie surowców, których potrzebujemy do przetrwania. Złota brakowało nawet u szczytu potęgi Przymierza.$b$bNa północnym zachodzie jest kopalnia złota, którą opanowały pająki. Potrzebujemy tego złota, ale trudno je wydobywać, gdy wszędzie łażą pająki. Nie mam wielu rąk do tej roboty, więc trzeba będzie załatwiać to po kawałku.$B$BIdź tam i zobacz, co możesz dla nas zrobić, $n.', 'Egzekutor Arren chce, żebyś $gzabił:zabiła; 8 młodych pająków Nocnej Sieci i 5 pająków Nocnej Sieci.', '', 'Wróć do egzekutora Arrena w Podzwonnem na Polanach Tirisfal.', '', '', '', '', 0),
(381, 'koKR', 'Szkarłatna Krucjata', 'Ucieszy cię wieść, że w kopalni chyba robimy postępy, w niemałej mierze dzięki tobie. Możemy teraz zwrócić uwagę na inne sprawy.$b$bMoi zwiadowcy donoszą, że oddział Szkarłatnej Krucjaty rozbija obóz na południowy wschód stąd. Szkarłatna Krucjata to godna pogardy organizacja, która na nas poluje i nie spocznie, dopóki każdy nieumarły – sługa Plagi Króla Lisza czy nie – nie zostanie zniszczony. Musimy uderzyć pierwsi!$b$bUważaj, ich bezbożna żarliwość czyni z nich groźnych przeciwników.', 'Przynieś egzekutorowi Arrenowi 12 szkarłatnych opasek od szkarłatnych konwertytów i szkarłatnych nowicjuszy.', '', 'Wróć do egzekutora Arrena w Podzwonnem na Polanach Tirisfal.', '', '', '', '', 0),
(382, 'koKR', 'Czerwony posłaniec', 'Moi przełożeni w Brill donoszą, że ze Szkarłatnego Klasztoru wysłano tu, do Podzwonnego, agenta Szkarłatnej Krucjaty. Według raportów posłaniec ma przy sobie ważne informacje. Nie znam szczegółów, ale cokolwiek to jest, musimy to zdobyć!$b$bJesteś najlepiej przygotowaną osobą, jaką mogę tam posłać, $n. Znajdź tego posłańca i przynieś mi wszystkie informacje, jakie zdołasz znaleźć.', 'Zabij posłańca Mevena Korgala w obozie krzyżowców, a potem dostarcz egzekutorowi Arrenowi wszelkie znalezione informacje.', '', 'Wróć do egzekutora Arrena w Podzwonnem na Polanach Tirisfal.', '', '', '', '', 0),
(383, 'koKR', 'Kluczowe informacje', 'Trzeba to zanieść mojemu przełożonemu, egzekutorowi Zygandowi, do Brill. Dzięki tym informacjom zadamy Szkarłatnej Krucjacie decydujący cios. Twoje usługi przydały się tu, w Podzwonnem, ale potrzebuję kogoś, kto dostarczy to Zygandowi, a on na pewno znajdzie ci bardziej odpowiednią robotę.$b$bWyjdź z Podzwonnego drogą na północ. Wkrótce po wejściu do właściwego Tirisfal dotrzesz do rozstajów. Skręć w odnogę na wschód i idź dalej na wschód. Po drodze miniesz Dwór Zimnego Paleniska.', 'Dostarcz dokumenty Szkarłatnej Krucjaty egzekutorowi Zygandowi w Brill.', '', '', '', '', '', '', 0),
(398, 'koKR', 'Poszukiwany: Robacze Oko', 'Poszukiwany: Robacze Oko!$b$bRobacze Oko, plugawa bestia nawet jak na gnola, zostało skazane na śmierć za zbrodnie przeciwko Porzuconym. Ten nikczemny złoczyńca kradnie zwłoki dla armii Króla Lisza. Ostatnio widziano go, gdy plądrował ziemie w pobliżu Nawiedziska Garrena, na północ od Brill.$b$bMiasto Brill niniejszym wyznacza nagrodę dla zdolnej duszy, która wykona egzekucję. Po dokonaniu dzieła pokaż egzekutorowi Zygandowi łapę złoczyńcy.$b$bLitość jest dla słabych.', 'Zabij Robacze Oko i wróć z jego łapą do egzekutora Zyganda w Brill po nagrodę.', '', 'Wróć do egzekutora Zyganda w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(404, 'koKR', 'Zgniła robota', 'Plaga przesączyła się na Polany Tirisfal i opanowała tereny na zachód od Brill, w pobliżu starego mostu.$B$BIdź tam i odeprzyj gnijące i zmasakrowane trupy, które napotkasz. Rozrzuć ich kości i przynieś ich gnijące pazury, a strażnicy śmierci cię wynagrodzą.', 'Przynieś 7 gnijących pazurów strażnikowi śmierci Dillingerowi w Brill.', '', 'Wróć do strażnika śmierci Dillingera w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(405, 'koKR', 'Lisz marnotrawny', 'Bethor Lodowy Odłamek, wysoko postawiony i potężny mag z Podmiasta na południu, każe mi przysłać mu agenta, który dowiódł swojej wartości w walce z Plagą. Tym agentem będziesz ty, $N.$B$BPrzedstaw te rozkazy Bethorowi. On przekaże ci szczegóły misji. Nie znam ich, ale chodzi o zwerbowanie zbłąkanego lisza. I będzie niebezpiecznie.$B$BWięc przygotuj się, $N. Nie możesz zawieść.$B$BBethora znajdziesz w Dzielnicy Magów w Podmieście.', 'Przedstaw rozkazy Sevrena Bethorowi Lodowemu Odłamkowi w Podmieście.', '', '', '', '', '', '', 0),
(407, 'koKR', 'Pola żałoby', 'Niewinne dynie, prawda? Tak by się mogło wydawać. Jeśli mamy odeprzeć natarcie Arthasa z północy i ludzką zarazę z południa, musimy zacząć w pełni wykorzystywać nasz dar nieżycia.$b$bOdrobina pomysłowości i zwykła dynia staje się agentem naszej Mrocznej Pani. Ta dynia, zaprawiona moją najnowszą recepturą, okaże się nie lada przysmakiem.$b$bSchwytano kolejnego szkarłatnego fanatyka i trzymamy go w piwnicy tawerny „Pod Szubienicą”. Zanieś tę dynię temu głupcowi.', 'Zanieś zaprawioną dynię pojmanemu szkarłatnemu fanatykowi, którego przetrzymują w piwnicy tawerny „Pod Szubienicą”.', '', '', '', '', '', '', 0),
(408, 'koKR', 'Rodzinna krypta', 'Okolice Młynówki Agamandów stały się przyczółkiem Plagi. Jej najsilniejszym punktem jest Krypta Rodu Agamandów, gdzie urządził sobie kwaterę miejscowy dowódca, szkielet zwany kapitanem Dargolem. Za pomocą nekromancji wskrzesił przodków Agamandów i zamierza użyć ich przeciwko nam.$B$BNie można do tego dopuścić – musisz to powstrzymać. Udaj się do Krypty Rodu Agamandów i pokonaj wskrzeszonych przodków Agamandów.$B$BI przynieś mi czaszkę kapitana Dargola.', 'Zabij 8 zawodzących przodkiń i 8 gnijących przodków.$B$BZabij kapitana Dargola i przynieś jego czaszkę sędziemu Sevrenowi w Brill.', '', 'Wróć do sędziego Sevrena w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(409, 'koKR', 'Dowód lojalności', 'Mówisz, że nie jesteś $gspętany:spętana; wolą Króla Lisza, a zaklęcie, które Bethor rzucił na moją księgę, to potwierdza. Ale zanim ci uwierzę, potrzebuję dowodu, że jesteś wrogiem Plagi.$B$BTuż przy południowym brzegu tej wyspy stoi stary, zakrwawiony ołtarz. Korzysta z niego potężna agentka Plagi, Lillith Nefara.$B$BWeź świecę wzywania z tej skrzyni. Zapal ją na ołtarzu, a Lillith się przebudzi. Zniszcz Lillith, a uwierzę, że jesteś wrogiem Króla Lisza.', 'Zdobądź świecę wzywania.$B$BPrzywołaj Lillith Nefarę i zabij ją.$B$BWróć do Gunthera na jego wyspie.', '', 'Wróć do Gunthera Arcanusa w Posterunku Krzyżowców na Polanach Tirisfal.', '', '', '', '', 0),
(410, 'koKR', 'Uśpiony cień', '', '', '', 'Wróć do stołu obiadowego Lillith na Zachodnich Plagowiskach.', '', '', '', '', 0),
(411, 'koKR', 'Powrót lisza marnotrawnego', 'Zanieś ten klejnot Otchłani mojemu staremu towarzyszowi Bethorowi. Pozwoli nam się porozumiewać... a mam mu wiele do powiedzenia.', 'Zanieś klejnot Otchłani Bethorowi Lodowemu Odłamkowi w Podmieście.', '', '', '', '', '', '', 0),
(426, 'koKR', 'Opanowane młyny', 'Plaga próbuje założyć bazę w Młynówce Agamandów. Jeśli jej się uda, będzie mogła przypuszczać stamtąd kolejne ataki w głąb Tirisfal.$B$BRozkazy zostały wydane. Plaga w Młynówce musi zostać zniszczona.$B$BIdź do Młynówki. Zbieraj wyszczerbione żebra od żołnierzy z Grzechoczących Klatek i z Pękniętych Czaszek oraz poczerniałe czaszki od kościomantów z Ciemnookich.$B$BŻeby dotrzeć do Młynówki, idź drogą na zachód. Za mostem skręć na najbliższym rozwidleniu na północ i idź dalej na północ. Gdy zobaczysz wiatraki, zacznie się bitwa.', 'Zbierz 5 wyszczerbionych żeber i 3 poczerniałe czaszki, a następnie wróć do strażnika śmierci Dillingera w Brill.', '', 'Wróć do strażnika śmierci Dillingera w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(427, 'koKR', 'Wojna ze Szkarłatną Krucjatą', 'Dokumenty dostarczone przez egzekutora Arrena to przełom, którego potrzebowaliśmy w walce z nędzną Szkarłatną Krucjatą. Teraz znamy dokładne położenie jej sił na całych Polanach Tirisfal.$b$bAle strażnicy śmierci mają większe zmartwienia. Armia Króla Lisza rośnie z każdą nocą. Potrzebujemy kogoś z „inicjatywą”, takiego jak ty, by zapędzić Szkarłatną Krucjatę do grobu.$b$bUdowodnij mi, że nadajesz się do służby Mrocznej Pani: wyrusz na zachód do wieży za Gospodarstwem Sollidenów i zabij 10 szkarłatnych wojowników.', 'Egzekutor Zygand z Brill chce, żebyś $gzabił:zabiła; 10 szkarłatnych wojowników.', '', 'Wróć do egzekutora Zyganda w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(431, 'koKR', 'Świece wzywania', '', '', '', '', '', '', '', '', 0),
(440, 'koKR', 'Grawerowany pierścień', 'Jeśli chcesz odnaleźć męża albo ukochanego, który dał Deliah ten pierścień... porozmawiaj z sędzią Sevrenem w Brill. Powinien mieć spis niedawnych zgonów i przy odrobinie szczęścia ustali, kim jest Deliah.$B$BAle nie robiłbym sobie nadziei. Ktokolwiek dał jej ten pierścień, pewnie nie żyje. A jeśli jest nieumarły, to Deliah pewnie już go nie obchodzi.', 'Zanieś pierścień Deliah sędziemu Sevrenowi w Brill.', '', '', '', '', '', '', 0),
(441, 'koKR', 'Raleigh i Podmiasto', 'Deliah miała męża, Raleigha, który mieszka teraz w Podmieście. Jeśli ten pierścień należał do Deliah z Brill, Raleigh będzie o tym wiedział.$B$BRaleigh przebywa w Dzielnicy Handlowej Podmiasta.', 'Zanieś pierścień Deliah Raleighowi.', '', '', '', '', '', '', 0),
(445, 'koKR', 'Dostawa do Srebrzystego Boru', 'Ci, którzy służą Lady Sylwanie, nie mogą sobie pozwolić na luksus czasu. Z pewnością już to wiesz.$b$bJako członek Królewskich Zakładów Chemicznych mam obowiązek dzielić się wiedzą z kolegami, by nasze wspólne wysiłki dały pewnego dnia Mrocznej Pani Nową Zarazę, której tak bardzo pragnie.$b$bZanieś te wyniki badań aptekarzowi Renferrelowi, który stacjonuje w Grobowisku w Srebrzystym Borze. Z Brill idź drogami na południe. Od Podmiasta kieruj się na południowy zachód.', 'Zanieś wyniki badań aptekarza Johaana aptekarzowi Renferrelowi w Srebrzystym Borze.', '', '', '', '', '', '', 0),
(492, 'koKR', 'Nowa zaraza', 'Według strażników śmierci właśnie schwytano kolejnego z tych głupich krasnoludzkich górskich strażników. Strażnicy śmierci lubią trzymać więźniów w piwnicy tawerny „Pod Szubienicą”, dopóki nie zajmą się nimi „jak należy”.$b$bMoże pójdziesz sprawdzić, jak pojmanemu górskiemu strażnikowi smakuje specjalny napój, który dla niego przyrządziłem? Zawiera subtelną zapowiedź tego, co Mroczna Pani szykuje dla reszty Azeroth.', 'Zanieś specjalny napój Johaana pojmanemu górskiemu strażnikowi.', '', '', '', '', '', '', 0),
(590, 'koKR', 'Łotrowski interes', 'Co?$B$BCo?!$B$BChcesz kasy? Nie jestem ci winien żadnej kasy.$B$BList? Jaki list? A, chcesz się bić? No dobra, $gkolego:koleżanko;... zaczynamy! Winien ci kasę, też coś...', 'Pokonaj Calvina Montague\'a w Podzwonnem.', 'Pokonaj Calvina Montague\'a', 'Wróć do Calvina Montague\'a w Podzwonnem.', '', '', '', '', 0),
(838, 'koKR', 'Scholomancjum', 'Na wyspie Caer Darrow leży Scholomancjum – szkoła, która służy Pladze za twierdzę. Nasz wróg mieszka w niej i w spokoju prowadzi badania, które zwiększają jego moc. Drogę zagradzają drzwi i mimo naszych starań nie da się wejść bez odpowiedniego klucza.$B$BAptekarz Dithers dobrze zna Scholomancjum i ma pomysł, jak zdobyć klucz. $GDowiodłeś:Dowiodłaś; mi, że potrafisz załatwiać sprawy, więc teraz tobie powierzam to zadanie. Porozmawiaj z nim o tym.', 'Porozmawiaj z aptekarzem Dithersem na Barykadzie na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(964, 'koKR', 'Fragmenty szkieletów', 'Klucz do Scholomancjum nazywa się wytrychem. Trzeba go wykuć ze szczątków szkieletu – a właściwie kilku – i zahartować w odpowiedniej formie tylko najtwardszymi z metali. Ostatecznie zadziała dopiero dzięki pieczęci mocy istoty, która z natury potrafi otworzyć portal do Scholomancjum.$B$BAle po kolei, $N. Do wykucia klucza potrzebujemy fragmentów szkieletów. Szkielety w Andorhalu powinny dać nam to, czego trzeba, ale te spod murów też mogą się nadać.', 'Przynieś 15 fragmentów szkieletów aptekarzowi Dithersowi na Barykadę na Zachodnich Plagowiskach.', '', 'Wróć do aptekarza Dithersa na Barykadzie na Polanach Tirisfal.', '', '', '', '', 0),
(1478, 'koKR', 'Wezwanie Halgara', 'Ach, $n! Właśnie dostałem wiadomość od Carendina Halgara, że chciałby cię widzieć na dalszym szkoleniu.$b$bMożesz być z siebie $gdumny:dumna;, $n. Nie co dzień mistrz Halgar osobiście raczy uczyć $gmłodego czarnoksiężnika:młodą czarnoksiężniczkę;.$b$bZnajdziesz go w Dzielnicy Magów Podmiasta, niedaleko Świątyni Potępionych.', 'Porozmawiaj z Carendinem Halgarem w Podmieście.', '', '', '', '', '', '', 0),
(1818, 'koKR', 'Porozmawiaj z Dillingerem', 'Powiedziano mi, że strażnik śmierci Dillinger ma robotę dla kogoś takiego jak ty. Jeśli chcesz pokazać swoją wartość siłom Mrocznej Pani, natychmiast się do niego zgłoś.$B$BPosterunek strażnika śmierci Dillingera znajduje się na zachodnim krańcu Brill, obok cmentarza.', 'Porozmawiaj ze strażnikiem śmierci Dillingerem w Brill.', '', '', '', '', '', '', 0),
(1819, 'koKR', 'Ulag Tasak', 'Gdy Plaga przetoczyła się przez Polany Tirisfal, schwytaliśmy jednego z nich do badań. Miał wolny umysł i nazywał siebie Ulagiem Tasakiem. Ale choć jego wola była wolna, wciąż pozostawał w niewoli Króla Lisza.$B$BLiczyliśmy, że znajdziemy sposób, by zerwać władzę króla nad Ulagiem, ale nam się nie udało. Teraz wreszcie nadszedł czas, by go uwolnić.$B$BUwolnij go i zabij.$B$BUruchom kamienny mechanizm w kształcie czaszki przy mauzoleum na północy. Zdejmie on magiczną pieczęć, która go więzi.$B$BA potem... bądź $ggotów:gotowa;, $N.', 'Zabij Ulaga Tasaka, a potem porozmawiaj ze strażnikiem śmierci Dillingerem.', '', 'Wróć do strażnika śmierci Dillingera w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(1820, 'koKR', 'Porozmawiaj z Colemanem', '$GDowiodłeś:Dowiodłaś; swojej wartości Mrocznej Pani, teraz może dowiedziesz jej któremuś z jej poddanych.$B$BColeman Farthing czeka na wojownika, który zechce zostać narzędziem jego zemsty na wrogach Porzuconych.$B$BZnajdziesz go w tawernie „Pod Szubienicą” we wschodniej części Brill.', 'Porozmawiaj z Colemanem Farthingiem.', '', '', '', '', '', '', 0),
(1821, 'koKR', 'Pamiątki rodowe Agamandów', 'Za życia pracowałem dla rodu Agamandów i to oni byli przyczyną mojej śmierci! Jakże stosowne, że Agamandowie są teraz bezmyślnymi sługami Króla Lisza.$B$BTeraz chcę im odebrać resztki honoru. Idź do ich rodowej krypty i ograb ich z pamiątek rodowych: miecza, topora, sztyletu i maczugi. Przynieś mi je!$B$BKrypta rodu Agamandów znajduje się na północnym krańcu Młynówki Agamandów. Strzegą jej czająca się Plaga i martwi Agamandowie.', 'Przynieś Colemanowi Farthingowi topór rodu Agamandów, miecz rodu Agamandów, maczugę rodu Agamandów i sztylet rodu Agamandów.', '', 'Wróć do Colemana Farthinga w Brill na Polanach Tirisfal.', '', '', '', '', 0),
(1822, 'koKR', 'Broń rodowa', '', '', '', '', '', '', '', '', 0),
(1885, 'koKR', 'Mennet Carkad', '$n? Nie tego się spodziewałam, skoro sam Carkad się tobą zainteresował. Ale pozory mylą, prawda?$b$bTak czy inaczej, idź do niego jak najszybciej. $GNie chciałbyś:Nie chciałabyś; wiedzieć, co spotkało kilku ostatnich, którzy zlekceważyli jego wezwanie.', 'Porozmawiaj z Mennetem Carkadem w Dzielnicy Łotrów Podmiasta.', '', '', '', '', '', '', 0),
(3095, 'koKR', 'Prosty zwój', 'Ach, kiedy $gzajmowałeś:zajmowałaś; się bezmyślną Plagą, przyszedł do ciebie ten zwój. Sądzę, że to coś ważnego, bo nosi pieczęć nauczyciela wojowników Dannala. Na twoim miejscu przeczytałbym go, zanim znów wyruszysz.', 'Przeczytaj prosty zwój i porozmawiaj z Dannalem Sternem w Podzwonnem.', '', '', '', '', '', '', 0),
(3096, 'koKR', 'Zaszyfrowany zwój', 'Ach, kiedy $gzajmowałeś:zajmowałaś; się bezmyślną Plagą, przyszedł do ciebie ten zwój. Sądzę, że to coś ważnego, bo nosi pieczęć nauczyciela łotrów Davida Triasa. Na twoim miejscu przeczytałbym go, zanim znów wyruszysz.', 'Przeczytaj zaszyfrowany zwój i porozmawiaj z Davidem Triasem w Podzwonnem.', '', '', '', '', '', '', 0),
(3097, 'koKR', 'Uświęcony zwój', 'Ach, kiedy $gzajmowałeś:zajmowałaś; się bezmyślną Plagą, przyszedł do ciebie ten zwój. Sądzę, że to coś ważnego, bo nosi pieczęć nauczyciela kapłanów Duestena. Na twoim miejscu przeczytałbym go, zanim znów wyruszysz.', 'Przeczytaj uświęcony zwój i porozmawiaj z mrocznym klerykiem Duestenem w kościele w Podzwonnem.', '', '', '', '', '', '', 0),
(3098, 'koKR', 'Zwój z glifami', 'Ach, kiedy $gzajmowałeś:zajmowałaś; się bezmyślną Plagą, przyszedł do ciebie ten zwój. Sądzę, że to coś ważnego, bo nosi pieczęć nauczycielki magów Isabelli. Na twoim miejscu przeczytałbym go, zanim znów wyruszysz.', 'Przeczytaj zwój z glifami i porozmawiaj z Isabellą w kościele w Podzwonnem.', '', '', '', '', '', '', 0),
(3099, 'koKR', 'Skażony zwój', 'Ach, kiedy $gzajmowałeś:zajmowałaś; się bezmyślną Plagą, przyszedł do ciebie ten zwój. Sądzę, że to coś ważnego, bo nosi pieczęć nauczyciela czarnoksiężników Maximilliona. Na twoim miejscu przeczytałbym go, zanim znów wyruszysz.', 'Przeczytaj skażony zwój i porozmawiaj z Maximillionem w Podzwonnem.', '', '', '', '', '', '', 0),
(3901, 'koKR', 'Potrząsnąć Grzechoczącymi Klatkami', '$GPokazałeś:Pokazałaś; Porzuconym, na co cię stać w zwykłych warunkach, $N – teraz zobaczmy, jak radzisz sobie pod presją.$B$BSzkielety z Grzechoczących Klatek, kolejne bezmyślne sługi Króla Lisza, są groźniejszym przeciwnikiem niż zombie, z którymi $gmiałeś:miałaś; dotąd do czynienia. Znów przetrzeb ich szeregi i dowiedź swojej wartości Porzuconym. Nie zwlekaj – gdy skończysz, wróć do mnie.', 'Zabij 8 szkieletów z Grzechoczących Klatek, a gdy skończysz, wróć do kapłana cienia Sarvisa w Podzwonnem.', '', 'Wróć do kapłana cienia Sarvisa w Podzwonnem na Polanach Tirisfal.', '', '', '', '', 0),
(3902, 'koKR', 'Szabrowanie w Podzwonnem', 'Hej, ty! Jeśli szukasz sposobu, żeby się na coś przydać, to słuchaj!$B$BPotrzebujemy świeżo wygrzebanych z ziemi rekrutów, którzy przeszukają Podzwonne w poszukiwaniu wszelkiego przydatnego sprzętu. Najpewniej znajdzie się w stertach skrzyń. Wkrótce powstaną kolejni rekruci i jeśli nie chcemy, żeby łazili nago, lepiej weźmy się do szabrowania!$B$BNo, do roboty, ty żałosny worku kości! Nie zamierzam nagradzać obiboków.', 'Przeszukaj Podzwonne i okolice, zbierz 6 wyszabrowanych towarów i zanieś je strażnikowi śmierci Saltainowi.', '', 'Wróć do strażnika śmierci Saltaina w Podzwonnem na Polanach Tirisfal.', '', '', '', '', 0),
(5096, 'koKR', 'Szkarłatna dywersja', 'Zanim zajmiemy się Andorhalem, musimy rozprawić się z nacierającą Szkarłatną Krucjatą z Żagiewia. Rozbili obóz między Zagonem Felstone\'ów a Łzami Dalsona, przez co grozi nam walka jednocześnie z Plagą i Krucjatą.$B$BMój plan to napuścić ich na siebie: wyślę cię, byś $gzniszczył:zniszczyła; namiot dowodzenia, który tam rozstawili. Weź trochę płomieni w butelce z tej skrzyni ze środkami zapalającymi. Gdy namiot spłonie, zatknij przy nim ten sztandar Plagi. Przy odrobinie szczęścia zostawią nas w spokoju i skupią się na zemście na Pladze.', 'Udaj się do obozu Szkarłatnej Krucjaty między Zagonem Felstone\'ów a Łzami Dalsona i zniszcz ich namiot dowodzenia.$B$BUmieść sztandar Plagi w obozie, a potem wróć do najwyższego egzekutora Derringtona na Barykadzie na Zachodnich Plagowiskach.', 'Zniszcz namiot dowodzenia i zatknij sztandar Plagi w obozie', 'Wróć do najwyższego egzekutora Derringtona na Barykadzie na Polanach Tirisfal.', '', '', '', '', 0),
(5097, 'koKR', 'Od wieży do wieży', 'Za pomocą magicznego urządzenia zwanego pochodnią sygnałową możemy oznaczać wybrane cele dla przyszłych działań naszych wojsk. Sądzimy, że Plaga kieruje ruchami swoich oddziałów ze strażnic Andorhalu.$B$BTwoja misja: przedrzyj się przez obronę Andorhalu i umieść znaczniki we wszystkich czterech strażnicach. Aby umieścić znacznik, musisz stanąć w drzwiach wieży; potem sam ją oznaczy. Pochodnia ma tylko pięć ładunków, więc używaj ich rozważnie!', 'Oznacz pochodnią sygnałową każdą wieżę w Andorhalu; aby się udało, musisz stanąć w drzwiach wieży.$B$BGdy oznaczysz wszystkie cztery, zwróć pochodnię sygnałową dowódcy Ashlamowi Mężnopięściowi w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', '', 'Wróć do dowódcy Ashlama Mężnopięścia w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', 'Wieża nr 1 oznaczona', 'Wieża nr 2 oznaczona', 'Wieża nr 3 oznaczona', 'Wieża nr 4 oznaczona', 0),
(5098, 'koKR', 'Od wieży do wieży', 'Za pomocą magicznego urządzenia zwanego pochodnią sygnałową możemy oznaczać wybrane cele dla przyszłych działań naszych wojsk. Sądzimy, że Plaga kieruje ruchami swoich oddziałów ze strażnic Andorhalu.$B$BTwoja misja: przedrzyj się przez obronę Andorhalu i umieść znaczniki we wszystkich czterech strażnicach. Aby umieścić znacznik, musisz stanąć w drzwiach wieży; potem sam ją oznaczy. Pochodnia ma tylko pięć ładunków, więc używaj ich rozważnie!', 'Oznacz pochodnią sygnałową każdą wieżę w Andorhalu; aby się udało, musisz stanąć w drzwiach wieży.$B$BGdy oznaczysz wszystkie cztery, zwróć pochodnię sygnałową najwyższemu egzekutorowi Derringtonowi na Barykadzie na Zachodnich Plagowiskach.', '', 'Wróć do najwyższego egzekutora Derringtona na Barykadzie na Polanach Tirisfal.', 'Wieża nr 1 oznaczona', 'Wieża nr 2 oznaczona', 'Wieża nr 3 oznaczona', 'Wieża nr 4 oznaczona', 0),
(5215, 'koKR', 'Kotły Plagi', 'Na ziemiach dawnego Lordaeronu stoi osiem kotłów – cztery tutaj, na zachodzie, i kolejne cztery ukryte na wschodzie. Wyrzucają w powietrze trucizny, szerząc zarazę po całej krainie na rzecz Plagi.$B$BNekromancka potęga Kel\'Thuzada jest zbyt wielka, byśmy mogli po prostu je wyłączyć, ale chyba znaleźliśmy sposób, by obrócić je na naszą korzyść. Moja zastępczyni, arcykapłanka MacDonnell, poprowadzi cię w tym zadaniu; dalszą odprawę przekaże ci już ona.', 'Porozmawiaj z arcykapłanką MacDonnell w Punkcie Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5216, 'koKR', 'Cel: Zagon Felstone\'ów', 'Spośród czterech kotłów tu, na zachodzie, do tego na Zagonie Felstone\'ów może być najłatwiej się dostać. Plaga ma tam mniej doświadczone oddziały, choć nie należy ich lekceważyć.$B$BIdź na Zagon Felstone\'ów, na północny zachód od Andorhalu, i zmierz się z tamtejszym władcą kotła. Sądzimy, że ma klucz, który otworzy dostęp do kotła. Gdy go otworzysz, użyj tej butelki, by pobrać próbkę trucizn z wnętrza kotła; będzie nam potrzebna do badań nad przeciwśrodkiem.', 'Udaj się na Zagon Felstone\'ów na Zachodnich Plagowiskach, odnajdź i pokonaj tamtejszego władcę kotła. Może mieć klucz, który otworzy dostęp do kotła. Musisz mieć przy sobie pustą butelkę z Zagonu Felstone\'ów, by pobrać próbkę trucizn z wnętrza kotła.', '', 'Otwórz kocioł Plagi na Zagonie Felstone\'ów na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5219, 'koKR', 'Cel: Łzy Dalsona', 'Jeden z kotłów zarazy stoi na polu dawnego gospodarstwa, które nazywa się teraz Łzami Dalsona. Cóż, dziś nie uronimy ani jednej łzy – pokrzyżujemy plany Plagi i niech się dławi własnymi oparami!$B$BIdź do Łez Dalsona, niemal dokładnie na północ od Andorhalu, i zlikwiduj tamtejszego władcę kotła. Powinien mieć klucz, tak jak poprzedni, który pozwoli ci dostać się do kotła. Użyj tej butelki, by pobrać próbkę z jego wnętrza; każdy kocioł ma własną, odrębną mieszankę toksyn.', 'Udaj się do Łez Dalsona na Zachodnich Plagowiskach, odnajdź i pokonaj tamtejszego władcę kotła, a potem użyj jego klucza, by dostać się do kotła. Musisz mieć przy sobie pustą butelkę z Łez Dalsona, by pobrać próbkę trucizn z wnętrza kotła.', '', 'Wróć do kotła Plagi na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5222, 'koKR', 'Cel: Wijące się Nawiedzisko', 'Udało się otworzyć dwa kotły; będziesz mieć do nich dostęp bez ograniczeń, ale chcemy otworzyć też dwa pozostałe. Da nam to więcej możliwości wprowadzenia przeciwśrodka!$B$BTym razem uderzysz na kocioł w Wijącym się Nawiedzisku. Leży niemal dokładnie na wschód od Andorhalu, dość blisko zrujnowanych murów miasta; znów zlikwiduj tamtejszego władcę kotła i zabierz mu klucz. Użyj tej butelki, by pobrać próbkę z kotła.$B$BUdanych łowów, $N!', 'Udaj się do Wijącego się Nawiedziska na Zachodnich Plagowiskach, odnajdź i pokonaj tamtejszego władcę kotła, a potem użyj jego klucza, by dostać się do kotła. Musisz mieć przy sobie pustą butelkę z Wijącego się Nawiedziska, by pobrać próbkę trucizn z wnętrza kotła.', '', 'Otwórz kocioł Plagi nad Jeziorem Darrowmere na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5225, 'koKR', 'Cel: Plony Gahrrona', 'Ostatni pozostały kocioł stoi w gospodarstwie zwanym teraz Plonami Gahrrona. Strzegą go jedne z twardszych sług Plagi – upiory i duchy. Nie należy ich lekceważyć, $N.$B$BPlony Gahrrona leżą na północny wschód od nas, blisko miejsca, gdzie zaczynają się Wschodnie Plagowiska; znów zlikwiduj tamtejszego władcę kotła i zabierz mu klucz. Oto twoja pusta butelka na próbkę; przynieś mi ją pełną. Niech Światłość chroni cię podczas tej niebezpiecznej misji, $N.', 'Udaj się na Plony Gahrrona na Zachodnich Plagowiskach, odnajdź i pokonaj tamtejszego władcę kotła, a potem użyj jego klucza, by dostać się do kotła. Musisz mieć przy sobie pustą butelkę z Plonów Gahrrona, by pobrać próbkę trucizn z wnętrza kotła.', '', 'Zbadaj kocioł Plagi na Plonach Gahrrona na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5228, 'koKR', 'Kotły Plagi', 'Na ziemiach dawnego Lordaeronu stoi osiem kotłów – cztery na zachodzie i kolejne cztery okopane na wschodzie. Wyrzucają w powietrze trucizny, szerząc zarazę po całej krainie na rzecz Plagi.$B$BNekromancka potęga Kel\'Thuzada jest zbyt wielka, byśmy mogli po prostu je wyłączyć, ale chyba znaleźliśmy sposób, by obrócić je na naszą korzyść. Moja zastępczyni, kapłanka cienia Vandis, poprowadzi cię w tym zadaniu; dalszą odprawę przekaże ci już ona.', 'Porozmawiaj z kapłanką cienia Vandis na Barykadzie na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5229, 'koKR', 'Cel: Zagon Felstone\'ów', 'Spośród czterech kotłów na Zachodnich Plagowiskach do tego na Zagonie Felstone\'ów może być najłatwiej się dostać. Plaga ma tam mniej doświadczone oddziały, choć nie należy ich lekceważyć.$B$BIdź na Zagon Felstone\'ów, prosto na wschód stąd i na północny zachód od Andorhalu, i zmierz się z tamtejszym władcą kotła. Ma przy sobie klucz, który otworzy dostęp do kotła. Gdy go otworzysz, użyj tej butelki, by pobrać próbkę toksyn z kotła; będzie nam potrzebna do badań nad przeciwśrodkiem.', 'Udaj się na Zagon Felstone\'ów na Zachodnich Plagowiskach, odnajdź i pokonaj tamtejszego władcę kotła. Może mieć klucz, który otworzy dostęp do kotła. Musisz mieć przy sobie pustą butelkę z Zagonu Felstone\'ów, by pobrać próbkę trucizn z wnętrza kotła.', '', 'Otwórz kocioł Plagi na Zagonie Felstone\'ów na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5230, 'koKR', 'Powrót na Barykadę', 'Napełniasz butelkę trującą miksturą z kotła – wystarczy na próbkę do badań.$B$BZ trucizną w ręku pora wrócić do kapłanki cienia Vandis na Barykadzie, by zakończyć misję.', 'Zanieś pełną butelkę z Zagonu Felstone\'ów kapłance cienia Vandis na Barykadę na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5231, 'koKR', 'Cel: Łzy Dalsona', 'Jeden z kotłów zarazy stoi na polu dawnego gospodarstwa, które nazywa się teraz Łzami Dalsona. Dziś nikt nie będzie ronić łez, $N; musimy uderzyć na ten kocioł i zdobyć do niego dostęp!$B$BIdź do Łez Dalsona, niemal dokładnie na północ od Andorhalu, i zlikwiduj tamtejszego władcę kotła. Powinien mieć klucz, tak jak poprzedni, który pozwoli ci dostać się do wnętrza kotła. Użyj tej butelki, by pobrać próbkę z jego wnętrza; każdy kocioł ma własną, odrębną mieszankę toksyn.', 'Udaj się do Łez Dalsona na Zachodnich Plagowiskach, odnajdź i pokonaj tamtejszego władcę kotła, a potem użyj jego klucza, by dostać się do kotła. Musisz mieć przy sobie pustą butelkę z Łez Dalsona, by pobrać próbkę trucizn z wnętrza kotła.', '', 'Otwórz kocioł Plagi na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5232, 'koKR', 'Powrót na Barykadę', 'Ostrożnie napełniasz butelkę posoką z kotła, aż próbka wydaje ci się dość duża.$B$BZ trucizną w ręku pora wrócić do kapłanki cienia Vandis na Barykadzie, by zakończyć misję.', 'Zanieś pełną butelkę z Łez Dalsona kapłance cienia Vandis na Barykadę na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5233, 'koKR', 'Cel: Wijące się Nawiedzisko', 'Udało się otworzyć dwa kotły; będziesz mieć do nich dostęp bez ograniczeń, ale chcemy otworzyć też dwa pozostałe. Da nam to więcej możliwości wprowadzenia przeciwśrodka!$B$BTym razem uderzysz na kocioł w Wijącym się Nawiedzisku. Leży niemal dokładnie na wschód od Andorhalu, dość blisko zrujnowanych murów miasta; znów zlikwiduj tamtejszego władcę kotła i zabierz mu klucz. Użyj tej butelki, by pobrać próbkę z kotła.$B$BUdanych łowów, $N!', 'Udaj się do Wijącego się Nawiedziska na Zachodnich Plagowiskach, odnajdź i pokonaj tamtejszego władcę kotła, a potem użyj jego klucza, by dostać się do kotła. Musisz mieć przy sobie pustą butelkę z Wijącego się Nawiedziska, by pobrać próbkę trucizn z wnętrza kotła.', '', 'Otwórz kocioł Plagi nad Jeziorem Darrowmere na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5234, 'koKR', 'Powrót na Barykadę', 'Ostrożnie napełniasz pustą butelkę; próbka plugawej substancji, która kłębi się pod platformą kotła, chlupocze teraz w kruchym szklanym naczyniu.$B$BZ trucizną w ręku pora wrócić do kapłanki cienia Vandis na Barykadzie, by zakończyć misję.', 'Zanieś pełną butelkę z Wijącego się Nawiedziska kapłance cienia Vandis na Barykadę na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5235, 'koKR', 'Cel: Plony Gahrrona', 'Ostatni pozostały kocioł stoi w gospodarstwie zwanym teraz Plonami Gahrrona. Strzegą go jedne z twardszych sług Plagi – upiory i duchy. Nie należy ich lekceważyć, $N.$B$BPlony Gahrrona leżą daleko na wschód od Barykady, blisko miejsca, gdzie zaczynają się Wschodnie Plagowiska; znów zlikwiduj tamtejszego władcę kotła i zabierz mu klucz. Oto twoja pusta butelka na próbkę; przynieś mi ją pełną. Niech cienie osłaniają cię podczas tej niebezpiecznej misji, $N.', 'Udaj się na Plony Gahrrona na Zachodnich Plagowiskach, odnajdź i pokonaj tamtejszego władcę kotła, a potem użyj jego klucza, by dostać się do kotła. Musisz mieć przy sobie pustą butelkę z Plonów Gahrrona, by pobrać próbkę trucizn z wnętrza kotła.', '', 'Otwórz kocioł Plagi na Plonach Gahrrona na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5236, 'koKR', 'Powrót na Barykadę', 'Ostrożnie zakręcasz kurek w panelu, patrząc, jak cuchnąca posoka z kotła skapuje do pustej butelki.$B$BZ trucizną w ręku pora wrócić do kapłanki cienia Vandis na Barykadzie, by zakończyć misję.', 'Zanieś pełną butelkę z Plonów Gahrrona kapłance cienia Vandis na Barykadę na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5237, 'koKR', 'Misja wykonana!', '', '', '', '', '', '', '', '', 0),
(5238, 'koKR', 'Misja wykonana!', '', '', '', '', '', '', '', '', 0),
(5341, 'koKR', 'Fortuna rodu Barovów', 'W Scholomancjum spoczywa fortuna rodu Barovów. Ja, Alexi Barov, jestem jednym z dwóch ostatnich dziedziców rodu Barovów. Drugim jest mój brat, Weldon.$B$BWeldon, ten nędzny tchórz, uciekł podczas wojny i dzięki temu zachował swoje bezwartościowe ludzkie istnienie.$B$BTeraz szuka aktów własności, by przywłaszczyć sobie fortunę. Odzyskaj akty, zanim zrobi to mój brat, a obsypię cię bogactwem, o jakim ci się nie śniło!', 'Wyrusz do Scholomancjum i odzyskaj fortunę rodu Barovów. Składają się na nią cztery akty własności: Akt własności Caer Darrow, Akt własności Brill, Akt własności Smolnego Młyna i Akt własności Południowego Brzegu. Gdy wykonasz zadanie, wróć do Alexiego Barova.', '', 'Wróć do Alexiego Barova na Barykadzie na Polanach Tirisfal.', '', '', '', '', 0),
(5342, 'koKR', 'Ostatni z Barovów', 'Oczywiście, dopóki mój brat żyje, mogą się pojawić spory, kto jest głównym spadkobiercą rodzinnej fortuny. Do tego nie może dojść.$B$BMam nadzieję, że taka podła szumowina jak ty nie wzdraga się przed odrobiną morderstwa z zimną krwią.$B$BTo proste zadanie i spodziewam się, że je wykonasz – o ile chcesz odebrać nagrodę.$B$BWeldon siedzi pod ochroną Przymierza w Obozie Zimnych Wichrów, na wschodzie. Zabij go i przynieś mi jego głowę.$B$B<Alexi ziewa.>$B$BNo, pospiesz się.', 'Udaj się do Obozu Zimnych Wichrów – na terytorium Przymierza – i zamorduj Weldona Barova. Weź jego głowę i wróć do Alexiego Barova.$B$BUważaj, Weldona zapewne dobrze strzeże hołota z Przymierza.', '', 'Wróć do Alexiego Barova na Barykadzie na Polanach Tirisfal.', '', '', '', '', 0),
(5343, 'koKR', 'Fortuna rodu Barovów', 'Mój drogi brat Alexi. Jakim byłem głupcem, darując mu życie. Spojrzałem w twarz wroga, jednego z nieumarłych, i pozwoliłem mu żyć.$B$B<Weldon spluwa.>$B$BTeraz on szuka MOJEGO spadku. Do tego po prostu nie może dojść.$B$BZnajdź akty własności mojej rodziny, zanim ten podły nędznik położy na nich swoje kościste łapy, a wynagrodzę cię ogromnym bogactwem. Leżą w ruinach Scholomancjum. Pospiesz się!', 'Wyrusz do Scholomancjum i odzyskaj fortunę rodu Barovów. Składają się na nią cztery akty własności: Akt własności Caer Darrow, Akt własności Brill, Akt własności Smolnego Młyna i Akt własności Południowego Brzegu. Gdy wykonasz zadanie, wróć do Weldona Barova.', '', 'Wróć do Weldona Barova w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5344, 'koKR', 'Ostatni z Barovów', 'Akty odzyskane, zostało więc tylko jedno. Alexi musi zginąć. Gdy umrze, nie będę się już musiał obawiać, że jakaś banda pozbawionych skrupułów najemników zechce mojej głowy.$B$BTo proste zadanie. Alexi ukrywa się pod ochroną Hordy – na Barykadzie.$B$BNie, nie oczekuję, że po prostu do niego podejdziesz i go zabijesz. Chcę jego głowy! Jak ją zdobędziesz... cóż, to już twoja sprawa. Takie zachowanie jest poniżej kogoś o moim szlachetnym wychowaniu.', 'Udaj się na Barykadę – na terytorium Hordy – i zamorduj Alexiego Barova. Weź jego głowę i wróć do Weldona Barova.$B$BUważaj, Alexiego zapewne dobrze strzeże hordyjska hołota.', '', 'Wróć do Weldona Barova w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', 0),
