INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(214, 'koKR', 'Najdroższa Yvette,\n\nPowierzam ten list naszemu najszybszemu gońcowi. Modlę się, by zdołał przedrzeć się przez siły, które nas otaczają. I modlę się, byś przeczytała te słowa, bo to ostatnie, jakie ode mnie usłyszysz.\n\nJedyną pociechą w tych mrocznych dniach jest dla mnie ulga, że mój los cię ominie.', 0),
(223, 'koKR', 'Rozpowszechnić informacje wedle uznania.$B$BDowództwo regionalne Tirisfal$BKapitan Melrache$BKapitan Vachon$BKapitan Perrine$B$BRozkazy z polecenia najwyższego lorda.$B$BKapitanie Perrine, dalej umacniajcie pozycję przy wieży południowo-zachodniej (zgodnie z oznaczeniem). Dodatkowe zaopatrzenie zostanie wysłane w późniejszym terminie. Do tego czasu materiały należy pozyskiwać z okolicznych farm. Ponadto trzeba przeprowadzić dalszy zwiad i zebrać więcej informacji', 0),
(224, 'koKR', 'o organizacji nieumarłych w Brill.$B$BKapitanie Vachon, w pobliżu wieży północnej wzmógł się ruch nieumarłych. To powstanie należy stłumić szybko i zdecydowanie.$B$BKapitanie Melrache, niepokoi nas stopień zorganizowania nieumarłych w pobliżu granic Plagowisk. W nadchodzących tygodniach na waszą pozycję zostanie wysłany świeży oddział ludzi.$B$BChwała w Światłości', 0),
(244, 'koKR', 'Lordzie Bethorze Lodowy Odłamku,$B$Bzgodnie z twoimi poleceniami przysyłam ci agenta, o którego prosiłeś. To właśnie okaziciel tego listu.$B$BOsoba ta okazała się niezawodna i zdolna do wykonywania rozkazów, sprawdziła się w walce z siłami Plagi i to ją wybieram do twojej misji.$B$BNiech Ona panuje niepodzielnie,$B– Sędzia Sevren$B$B', 0),
(252, 'koKR', 'Obawiam się, że ojciec popełnił poważny błąd, gdy postanowił zostać i bronić naszego domu. Siły Plagi szaleją na Polanach Tirisfal i choć jesteśmy dobrze umocnieni i zaopatrzeni, po zdradzie mojego brata Devlina brakuje nam sił i ludzi, by odpierać ich nieustanne ataki. Jeśli otrzymasz ten list, Yvette, wiedz, że Devlin jest zdrajcą. ', 0),
(253, 'koKR', 'Devlin popadł w rozpacz i szukał ucieczki od naszego nieszczęsnego losu, a w tej ucieczce zawarł pakt z Plagą. Nie wiem, jaką cenę mu obiecano za zdradę, ale jestem pewien, że była przesiąknięta kłamstwami. Jeśli zobaczysz mojego brata, uciekaj przed nim. To potwór. Kilka nocy temu zamordował dwóch naszych wartowników i wpuścił przez wyłom niewielką grupę sług Plagi, prowadząc ich tam, gdzie spało wielu z nas. ', 0),
(254, 'koKR', 'Ich zasadzka była okrutna. Zabili jedną trzecią z nas, zanim zdołaliśmy ich pokonać. Teraz ledwie starcza nam ludzi, by pilnować granic. To tylko kwestia czasu, aż nasza zmęczona straż osłabnie, a Plaga zaatakuje. I choć tamtej przeklętej nocy widziałem twarz Devlina pośród zdesperowanych ludzi i wychudłych sług Plagi, wymknął się, zanim zdołałem go pochwycić. Może nie żyje, a może wciąż żyje jako agent Plagi. Tak czy inaczej, jest potworem. ', 0),
(255, 'koKR', 'Devlin ostrzegał nas, że jeśli spróbujemy stawić czoła Pladze, jesteśmy zgubieni. Mówił to, gdy tylko wkroczyli na Polany Tirisfal, na długo zanim otoczyli nasz dom. Może błagał nas, żebyśmy odeszli, a może napawał się naszą zgubą. Zawsze trudno było zrozumieć, czym kieruje się Devlin. Od dziecka był dla nas zagadką. ', 0),
(256, 'koKR', 'Ale miał rację. Jesteśmy zgubieni. Ród Agamandów wygaśnie. Choć wciąż żyję, wiem, że wkrótce będę martwy. Nie boję się i nie żałuję, że zostałem z rodziną. Ale moje ostatnie myśli będą należeć do ciebie. Żyj, moja ukochana Yvette, a ja odnajdę spokój. – Thurman ', 0),
(1906, 'koKR', 'Gdy polityka i rywalizacja siedmiu ludzkich królestw to przybierały na sile, to słabły, ród Strażników niezmiennie czuwał nad tym, by powstrzymać chaos. Przez lata było wielu Strażników, lecz w danym czasie magiczną moc Tirisfal dzierżył zawsze tylko jeden. Jedna z ostatnich Strażniczek tamtej epoki wsławiła się jako potężna wojowniczka walcząca z cieniem. ', 0),
(1907, 'koKR', 'Egwina, porywcza ludzka dziewczyna, zyskała uznanie Zakonu i przejęła płaszcz Strażnika. Z zapałem tropiła i tępiła demony, gdziekolwiek je znalazła, często jednak podważała autorytet zdominowanej przez mężczyzn Rady Tirisfal.', 0),
(1908, 'koKR', 'Uważała, że pradawne elfy i starcy przewodzący radzie myślą zbyt sztywno i brak im dalekowzroczności, by raz na zawsze położyć kres konfliktowi z chaosem. Zniecierpliwiona długimi dyskusjami i sporami, pragnęła dowieść swojej wartości wobec równych sobie i przełożonych, przez co w kluczowych chwilach często przedkładała męstwo nad mądrość.', 0),
(1909, 'koKR', 'W miarę jak rosło jej panowanie nad kosmiczną mocą Tirisfal, Egwina dowiedziała się o grupie potężnych demonów grasujących na lodowym północnym kontynencie, w Północnej Grani. Wyruszywszy na daleką północ, Egwina wytropiła demony w górach. Tam odkryła, że polują one na jedno z ostatnich ocalałych smoczych stad i wysysają z tych prastarych istot ich wrodzoną magię. ', 0),
(1910, 'koKR', 'Potężne smoki, które uciekły przed nieustannym pochodem śmiertelnych społeczności, okazały się zbyt słabe, by przeważyć nad mroczną magią Legionu. Egwina stawiła czoła demonom i z pomocą szlachetnych smoków wytępiła je. Lecz gdy ostatni demon został wygnany ze świata śmiertelnych, nad całą północą rozszalała się wielka burza.', 0),
(1911, 'koKR', ' Na niebie nad Północną Granią pojawiło się ogromne, mroczne oblicze. Sargeras, król demonów i władca Płonącego Legionu, stanął przed Egwiną, jeżąc się piekielną energią. Oznajmił młodej Strażniczce, że czas Tirisfal dobiega końca i że świat wkrótce ugnie się pod naporem Legionu. ', 0),
(1912, 'koKR', 'Dumna Egwina, przekonana, że dorówna groźnemu bogu, uwolniła swoją moc przeciw awatarowi Sargerasa. Z niepokojącą łatwością zmiażdżyła władcę demonów swoją mocą i zdołała zniszczyć jego fizyczną powłokę. Obawiając się, że duch Sargerasa przetrwa, Egwina zamknęła zrujnowane szczątki jego ciała w jednej z pradawnych sal Kalimdoru, które po upadku Studni Wieczności zatonęły na dnie morza. ', 0),
(1913, 'koKR', 'Egwina nigdy się nie dowiedziała, że postąpiła dokładnie tak, jak zaplanował Sargeras. Mimowolnie przypieczętowała los świata śmiertelnych, bo Sargeras w chwili śmierci swego ciała przeniósł ducha do osłabionego ciała Egwiny. Bez wiedzy młodej Strażniczki Sargeras miał się ukrywać w najmroczniejszych zakamarkach jej duszy przez wiele długich lat.', 0),
(2436, 'koKR', 'Nie lekceważ moich słów, $N. Nastał czas podstępów i oszustw we wszystkich narodach... nawet w naszym wielkim Podmieście. Wszyscy wierni Sylwanie pracują nad nadejściem nowej ery – ery, w której władzę będą sprawować Porzuceni. I choć nie władamy magią ani nie chwycimy za broń na naszych granicach, i my mamy do odegrania swoją rolę.$B$BOdszukaj mnie w gospodzie w Podzwonnem. Wtedy porozmawiamy dłużej.$B$B– David Trias, nauczyciel łotrów', 0),
(2443, 'koKR', 'Wielu z nas sięga po magię tajemną i boską, by dodać sobie sił, ale my wiemy lepiej, prawda, $N? Wiemy, że nasza broń jest naszym świętym symbolem, tarcza naszą księgą zaklęć, a kolczuga naszą mądrością.$B$BNawet w nieżyciu jesteśmy silni, a będziemy jeszcze silniejsi.$B$BZnajdź mnie w gospodzie w Podzwonnem. Opowiem ci więcej o tych i innych sprawach.$B$B– Dannal Stern, nauczyciel wojowników ', 0),
(2447, 'koKR', 'Zepsucie i zło, które według plotek idą w parze z magią tajemną, są niczym wobec bólu, którego już zaznaliśmy. Nie jesteśmy już ofiarami, $n. To my kierujemy własnym losem. Sylwana utorowała nam drogę – dowiodła, że nasza wola należy do nas; że nie jesteśmy już niewolnikami tego drania Arthasa.$BOdszukaj mnie w kościele, a udzielę ci dalszych nauk... jeśli tego pragniesz.$B$B– Isabella, nauczycielka magów', 0),
(2452, 'koKR', 'Straszne położenie, w jakim się znaleźliśmy, prawda, $N? Nękani przez Plugawego Księcia. Odtrąceni i wzgardzeni przez naszych bliskich. Dzięki pięknej Sylwanie mamy w końcu własną wolę, ale co nam to teraz daje? Niewolnik innego pana to wciąż niewolnik, tak przynajmniej uważam.$B$BA gdyby to nas uczynić panami? Tak, wiesz, co mam na myśli, prawda?$B$BJesteśmy jeszcze bardziej odsunięci od reszty Porzuconych, $N. I dlatego musimy porozmawiać. Znajdź mnie w kościele w Podzwonnem. ', 0),
(2467, 'koKR', 'Ciesz się, że twój duch nie uleciał do Otchłani, $N. Ciesz się jeszcze bardziej, że uznałem cię za $gwartego:wartą; trudu napisania tego zwoju.$B$BLudzi, których niegdyś $gznałeś:znałaś;, a może nawet na których ci zależało, już nie ma! Musisz nauczyć się z tym „żyć” przez resztę swojego nienaturalnego już życia. Radzę, byś najpierw $gnauczył:nauczyła; się sobie z tym radzić.$B$BJeśli uważasz, że jesteś $ggotów:gotowa; na czekające cię próby, odszukaj mnie w kościele w Podzwonnem.$B$B– Mroczny kleryk Duesten, nauczyciel kapłanów', 0),
(3378, 'koKR', 'NIEZŁOMNY$B$BUkochany rumak księcia Arthasa Menethila$B$BWierny i wielkiego serca za życia – obyś w śmierci odnalazł spokój.$B$BCzystych strumieni i zielonych pastwisk, oddany przyjacielu.', 0);
