INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(314, 'koKR', 'Te ziemie zostaną oczyszczone!', '', 0),
(316, 'koKR', 'Te nieumarłe plugastwa zostaną zniszczone!', '', 0),
(317, 'koKR', 'Szkarłatna Krucjata nie zawiedzie w swojej misji!', '', 0),
(327, 'koKR', '*westchnienie* Pora znów zajrzeć na cmentarz – wrócę za kilka minut.', '', 0),
(328, 'koKR', 'Naprawdę powinniśmy wkrótce naprawić ten płot.', '', 0),
(370, 'koKR', 'Musimy zachować czujność, by wyplenić tę zarazę!', '', 0),
(371, 'koKR', 'Tak trzymać. Ta plaga zostanie wypleniona!', '', 0),
(372, 'koKR', 'Szkarłatna Krucjata oczyści te ziemie do cna!', '', 0),
(373, 'koKR', 'Niech nie przeżyje nikt, kogo skalała plugawa zaraza!', '', 0),
(425, 'koKR', 'Ja... ja... źle... się... czuję...', '', 0),
(427, 'koKR', '$gZakłóciłeś:Zakłóciłaś; mój spoczynek, $N. Teraz poczuj mój gniew!', '', 0),
(428, 'koKR', 'Mój umysł... moje ciało... ja... gniję...!', '', 0),
(513, 'koKR', '%s intonuje słowa mocy...', '', 0),
(514, 'koKR', 'Nie! To niemożliwe...', '', 0),
(515, 'koKR', 'Niesłychane! Znam tego, kto rzucił te zaklęcia...', '', 0),
(516, 'koKR', 'Tego się nie spodziewałem. Istota, która to zaczarowała, jest mi znana...', '', 0),
(517, 'koKR', '$n, mam informacje, których szukasz...', '', 0),
(567, 'koKR', 'Mieli mnie za słabeusza. Ha, ha!!', '', 0),
(568, 'koKR', 'To ja jestem głową rodziny. Ja. JA!!!', '', 0),
(569, 'koKR', 'Zimno mi, panie. Kiedy dotrzymasz obietnicy?', '', 0),
(570, 'koKR', 'Rodzina mnie nienawidzi. Zastraszeni idioci, wszyscy co do jednego!', '', 0),
(571, 'koKR', 'Ojcze? Jesteś teraz ze mnie dumny? HA, HA, HA!', '', 0),
(572, 'koKR', 'Matko, och, matko. Trzeba mnie było słuchać...', '', 0),
(573, 'koKR', 'Thurmanie, bracie, kto się teraz śmieje? Ha!', '', 0),
(574, 'koKR', 'Przychodzisz odwiedzić rodzinkę? Giń, głupcze!', '', 0),
(575, 'koKR', 'Młynówka Agamandów należy do Plagi, $N. Przyłącz się do nas!', '', 0),
(576, 'koKR', 'Wznoszę kufel i mam nadzieję, że pozbędę się takich jak ty! Twoje zdrowie, ty nicponiu, $n!', '', 0),
(885, 'koKR', '%s warzy miksturę dla $n.', '', 0),
(1013, 'koKR', 'Weź Świecę wzywania z tej skrzyni, $n.', '', 0),
(1480, 'koKR', '%s zaczyna tańczyć.', '', 0),
(1976, 'koKR', 'Żegnaj, przyjacielu.', '', 0),
(2625, 'koKR', 'Nosisz na sobie skazę Plagi. Szykuj się na podróż do Wypaczonej Otchłani.', 'Nosisz na sobie skazę Plagi. Szykuj się na podróż do Wypaczonej Otchłani.', 0),
(2626, 'koKR', 'Nie ma dla ciebie ucieczki. Krucjata zniszczy wszystkich skalanych przez Plagę.', 'Nie ma dla ciebie ucieczki. Krucjata zniszczy wszystkich skalanych przez Plagę.', 0),
(2627, 'koKR', 'Światłość potępia każdego, kto skrywa w sobie zło. A teraz giń!', 'Światłość potępia każdego, kto skrywa w sobie zło. A teraz giń!', 0),
(2628, 'koKR', 'Szkarłatna Krucjata pokarze niegodziwych i wypędzi zło z tych ziem!', 'Szkarłatna Krucjata pokarze niegodziwych i wypędzi zło z tych ziem!', 0),
(2631, 'koKR', 'Ha! Wieczne nieżycie przeklętym Agamandom!', '', 0),
(2632, 'koKR', 'Dziękuję ci, $n. $gOstudziłeś:Ostudziłaś; zimny gniew w moim sercu.', '', 0),
(3043, 'koKR', 'Dobra, dobra... daj mi chwilę odsapnąć. Nieźle mi $gprzyłożyłeś:przyłożyłaś;.', '', 0),
(4921, 'koKR', 'Za Hordę!', 'Za Hordę!', 0),
(4965, 'koKR', 'Brat mówił, że na tym szlaku handlowym zarobimy kupę forsy, ale nie wspomniał, że to ja wyląduję po tej stronie. Jeśli będziesz tu wracać sterowcem, przywieziesz mi coś do jedzenia? W Orgrimmarze sprzedają jedno z najlepszych mięs, a przydałoby mi się coś, co nie zdechło na kilka tygodni przed tym, jak przestało się ruszać.', 'Brat mówił, że na tym szlaku handlowym zarobimy kupę forsy, ale nie wspomniał, że to ja wyląduję po tej stronie. Jeśli będziesz tu wracać sterowcem, przywieziesz mi coś do jedzenia? W Orgrimmarze sprzedają jedno z najlepszych mięs, a przydałoby mi się coś, co nie zdechło na kilka tygodni przed tym, jak przestało się ruszać.', 0),
(5052, 'koKR', 'To tu jest najlepszy, najnowocześniejszy środek transportu, jaki można zbudować za pieniądze. Co? Podziemna kolejka? Gnomy? Słuchaj, kolego, jeśli wierzysz w te bzdury, to mam do sprzedania posąg w Dolinie Cierniodławów. No więc, idziesz do Grom\'gol na piechotę czy polecisz z klasą tą wspaniałą maszyną latającą? Twój wybór.', '', 0),
(5274, 'koKR', 'Witaj w Tanaris, $n. W czym mogę ci dziś służyć? Nie wyglądasz mi na kowala, ale wiem, że wygląd potrafi mylić.', '', 0),
(5955, 'koKR', 'Co może tak długo trwać?', '', 0),
(5956, 'koKR', 'Ile można zbierać garść chwastów?', '', 0),
(5957, 'koKR', 'W tym tempie sam bym je zebrał!', '', 0),
(5958, 'koKR', 'Jak chcesz, żeby coś było zrobione porządnie, zrób to sam!', '', 0),
(5959, 'koKR', 'Jakbym miał całą wieczność.', '', 0),
(5960, 'koKR', 'Ach, to pewnie on... nie? Phi!', '', 0),
(5961, 'koKR', 'Może trzeba było po prostu kupić trochę od Faruzy?', '', 0),
(5962, 'koKR', 'Musiałem zarekwirować plugastwo... plugastwo!', '', 0),
(6479, 'koKR', '', 'Nadszedł czas, $gtowarzyszu:towarzyszko; broni, by odebrać noc Pladze!', 0),
(6480, 'koKR', '', 'Nadszedł czas, $gtowarzyszu:towarzyszko; broni, by odebrać noc Pladze!', 0),
(6513, 'koKR', 'Chcę kupić od ciebie tajemny przyspieszacz.', 'Chcę kupić od ciebie tajemny przyspieszacz.', 0),
(6514, 'koKR', 'Nadciąga porywisty wiatr – czuję to po łupaniu w odsłoniętym kolanie. Oby tylko nas nie porwał.', '', 0),
(6515, 'koKR', 'No to, $n, bierzmy się do roboty przy tych kotłach! Jeśli masz zbierać potrzebne składniki, weź ode mnie szklisty skupiacz. Musisz go mieć przy sobie, żeby rozpoznać w sługach Plagi zasoby, które pozwolą odwrócić działanie tych kotłów.$B$BDo kotłów potrzebna ci też będzie dawka tajemnego przyspieszacza. Nie jest ani tani, ani stabilny. Gdy go już kupisz, masz tylko trzydzieści minut na użycie, zanim straci moc – kupuj więc z głową.', '', 0),
(6516, 'koKR', 'Czego potrzeba do kotła na Zagonie Felstone\'ów?', 'Czego potrzeba do kotła na Zagonie Felstone\'ów?', 0),
(6517, 'koKR', 'Czego potrzeba do kotła przy Łzach Dalsona?', 'Czego potrzeba do kotła przy Łzach Dalsona?', 0),
(6518, 'koKR', 'Czego potrzeba do kotła w Wijącym się Nawiedzisku?', 'Czego potrzeba do kotła w Wijącym się Nawiedzisku?', 0),
(6519, 'koKR', 'Czego potrzeba do kotła na Plonach Gahrrona?', 'Czego potrzeba do kotła na Plonach Gahrrona?', 0),
(6520, 'koKR', 'Na podstawie dostarczonej przez ciebie próbki toksyny sądzimy, że potrzebne będą: tajemny przyspieszacz, sześć kostnych pobudzaczy i cztery kawałki runicznej tkaniny. Ze szklistym skupiaczem przy sobie zdobądź pobudzacze ze szkieletowych nieumarłych tu, na Plagowiskach!$B$BGdy zdobędziesz te przedmioty, powinno ci się udać załadować przeciwśrodek do tamtego kotła.', '', 0),
(6522, 'koKR', 'Na podstawie dostarczonej przez ciebie próbki toksyny sądzimy, że potrzebne będą: tajemny przyspieszacz, pięć somatycznych wzmacniaczy i cztery kawałki runicznej tkaniny. Ze szklistym skupiaczem przy sobie zdobądź wzmacniacze z nieumarłych zombie i ghuli tu, na Plagowiskach!$B$BGdy zdobędziesz te przedmioty, powinno ci się udać załadować przeciwśrodek do tamtego kotła.', '', 0),
(6523, 'koKR', 'Na podstawie dostarczonej przez ciebie próbki toksyny sądzimy, że potrzebne będą: tajemny przyspieszacz, cztery ektoplazmatyczne rezonatory i cztery kawałki runicznej tkaniny. Ze szklistym skupiaczem przy sobie zdobądź rezonatory z upiorów i nieumarłych duchów tu, na Plagowiskach!$B$BGdy zdobędziesz te przedmioty, powinno ci się udać załadować przeciwśrodek do tamtego kotła.', '', 0),
(6525, 'koKR', 'No to, $n, bierzmy się do roboty przy tych kotłach! Jeśli masz zbierać potrzebne składniki, weź ode mnie szklisty skupiacz. Musisz go mieć przy sobie, żeby rozpoznać w sługach Plagi zasoby, które pozwolą odwrócić działanie tych kotłów.$B$BDo kotłów potrzebna ci też będzie dawka tajemnego przyspieszacza. Nie jest ani tani, ani stabilny. Gdy go już kupisz, masz tylko trzydzieści minut na użycie, zanim straci moc – kupuj więc z głową.', '', 0),
(6531, 'koKR', 'Potrzebuję szklistego skupiacza.', 'Potrzebuję szklistego skupiacza.', 0),
(6551, 'koKR', 'Plaga jest w naszym ręku – zmieniona zaraza będzie na nią działać jeszcze co najmniej przez całą dobę! Musimy jednak trzymać rękę na pulsie, więc sabotuj kotły, kiedy tylko możesz.', 'Plaga jest w naszym ręku – zmieniona zaraza będzie na nią działać jeszcze co najmniej przez całą dobę! Musimy jednak trzymać rękę na pulsie, więc sabotuj kotły, kiedy tylko możesz.', 0),
(6552, 'koKR', 'Jak nam idzie walka o przejęcie kotłów?', 'Jak nam idzie walka o przejęcie kotłów?', 0),
(6554, 'koKR', 'Akty własności są moje, bracie! Wkrótce na dobre zejdziesz mi z drogi!', '', 0),
(6642, 'koKR', '', 'Skoro kotły zostały otwarte, możemy wprowadzić przeciwśrodek do otoczenia. Niech Plaga posmakuje własnego lekarstwa, że się tak wyrażę!$B$BO odczynniki potrzebne do kotłów pytaj aptekarza Dithersa. Ja zajmuję się wszystkimi raportami o tym, jak ogólnie idzie nam obracanie zarazy przeciwko Pladze!', 0),
(6729, 'koKR', 'W Brill nie mamy banku, musisz się po to udać do Podmiasta. Na tyłach Ruin Lordaeronu, na południe stąd, są windy, które zawiozą cię na dół, do Podmiasta. Na miejscu zapytaj któregoś ze strażników Podmiasta o dokładniejszą drogę.', 'W Brill nie mamy banku, musisz się po to udać do Podmiasta. Na tyłach Ruin Lordaeronu, na południe stąd, są windy, które zawiozą cię na dół, do Podmiasta. Na miejscu zapytaj któregoś ze strażników Podmiasta o dokładniejszą drogę.', 0),
(6730, 'koKR', 'Do czego ci niby bank? No dobrze, musisz przejść przez Ruiny Lordaeronu na południe od Brill. Na tyłach są windy prowadzące w dół, do Podmiasta. Gdy tam dotrzesz, zatrzymaj któreś z tych ociężałych plugastw, które nazywają strażnikami Podmiasta, i zapytaj je o lepsze wskazówki.', 'Do czego ci niby bank? No dobrze, musisz przejść przez Ruiny Lordaeronu na południe od Brill. Na tyłach są windy prowadzące w dół, do Podmiasta. Gdy tam dotrzesz, zatrzymaj któreś z tych ociężałych plugastw, które nazywają strażnikami Podmiasta, i zapytaj je o lepsze wskazówki.', 0),
(6731, 'koKR', 'Treser nietoperzy jest w Podmieście. Idź drogą na południe z Brill, a na rozwidleniu skręć na zachód. Ruiny Lordaeronu będą po twojej lewej. Wejdź do nich, a potem zjedź na dół, do Podmiasta. Tam możesz poprosić o dalszą pomoc strażnika Podmiasta.', 'Treser nietoperzy jest w Podmieście. Idź drogą na południe z Brill, a na rozwidleniu skręć na zachód. Ruiny Lordaeronu będą po twojej lewej. Wejdź do nich, a potem zjedź na dół, do Podmiasta. Tam możesz poprosić o dalszą pomoc strażnika Podmiasta.', 0),
(6732, 'koKR', 'Chcesz gdzieś polecieć? Musisz się po to udać do Podmiasta! Idź drogą na południe z miasteczka, potem na południowy zachód do Ruin Lordaeronu. Z tyłu ruin zjedziesz windą do Podmiasta, a tam zapytaj strażnika Podmiasta o dokładniejszą drogę.', 'Chcesz gdzieś polecieć? Musisz się po to udać do Podmiasta! Idź drogą na południe z miasteczka, potem na południowy zachód do Ruin Lordaeronu. Z tyłu ruin zjedziesz windą do Podmiasta, a tam zapytaj strażnika Podmiasta o dokładniejszą drogę.', 0),
(6733, 'koKR', 'Karczmarkę Renee znajdziesz w tawernie „Pod Szubienicą”, na południowo-wschodnim końcu ulicy biegnącej przez miasteczko.', 'Karczmarkę Renee znajdziesz w tawernie „Pod Szubienicą”, na południowo-wschodnim końcu ulicy biegnącej przez miasteczko.', 0),
(6734, 'koKR', 'Gdzie też mogłaby się podziewać karczmarka Renee? Hmm? Och, może w tawernie „Pod Szubienicą”. Tak, na pewno tam. Spróbuj na południowo-wschodnim krańcu Brill... dasz radę trafić?', 'Gdzie też mogłaby się podziewać karczmarka Renee? Hmm? Och, może w tawernie „Pod Szubienicą”. Tak, na pewno tam. Spróbuj na południowo-wschodnim krańcu Brill... dasz radę trafić?', 0),
(6735, 'koKR', 'Nauczyciela magów, Caina Ognistą Pieśń, znajdziesz na górnym podeście w tawernie „Pod Szubienicą”, na południowo-wschodnim krańcu Brill. Pewnie zameldował się za późno, żeby dostać pokój.', 'Nauczyciela magów, Caina Ognistą Pieśń, znajdziesz na górnym podeście w tawernie „Pod Szubienicą”, na południowo-wschodnim krańcu Brill. Pewnie zameldował się za późno, żeby dostać pokój.', 0),
(6736, 'koKR', 'Wyglądam ci na kogoś, kto rzuca czary? No, doszły mnie słuchy, że Cain Ognista Pieśń przesiaduje na górnym podeście w tawernie „Pod Szubienicą”, na południowo-wschodnim krańcu miasteczka. Dziwne, że tak sobie stoi pod drzwiami pokoju Gretchen.', 'Wyglądam ci na kogoś, kto rzuca czary? No, doszły mnie słuchy, że Cain Ognista Pieśń przesiaduje na górnym podeście w tawernie „Pod Szubienicą”, na południowo-wschodnim krańcu miasteczka. Dziwne, że tak sobie stoi pod drzwiami pokoju Gretchen.', 0),
(6737, 'koKR', 'Na południowo-wschodnim skraju miasteczka jest tawerna „Pod Szubienicą”. Idź tam, wejdź na górę, a w czytelni znajdziesz mrocznego kleryka Beryla.', 'Na południowo-wschodnim skraju miasteczka jest tawerna „Pod Szubienicą”. Idź tam, wejdź na górę, a w czytelni znajdziesz mrocznego kleryka Beryla.', 0),
(6738, 'koKR', 'Ach, szukasz mrocznego kleryka Beryla. Jest na górze, w czytelni w tawernie „Pod Szubienicą”. Czyta, modli się, kto wie, co on tam robi – i kto by śmiał zapytać?', 'Ach, szukasz mrocznego kleryka Beryla. Jest na górze, w czytelni w tawernie „Pod Szubienicą”. Czyta, modli się, kto wie, co on tam robi – i kto by śmiał zapytać?', 0),
(6739, 'koKR', 'Nauczycielka łotrów nazywa się Marion Call. Znajdziesz ją na górze, w czytelni w tawernie „Pod Szubienicą”, na południowo-wschodnim skraju miasteczka.', 'Nauczycielka łotrów nazywa się Marion Call. Znajdziesz ją na górze, w czytelni w tawernie „Pod Szubienicą”, na południowo-wschodnim skraju miasteczka.', 0),
(6740, 'koKR', 'Marion Call dotrzymuje towarzystwa mrocznemu klerykowi Berylowi w czytelni na górze w tawernie „Pod Szubienicą”, na południowo-wschodnim skraju Brill. Umieram z ciekawości, kto wygra ten pojedynek na spojrzenia.', 'Marion Call dotrzymuje towarzystwa mrocznemu klerykowi Berylowi w czytelni na górze w tawernie „Pod Szubienicą”, na południowo-wschodnim skraju Brill. Umieram z ciekawości, kto wygra ten pojedynek na spojrzenia.', 0),
(6741, 'koKR', 'Nazywa się Rupert Boch. Podobno zajmuje jeden z pokoi na górze w tawernie „Pod Szubienicą”, na południowo-wschodnim krańcu miasteczka.', 'Nazywa się Rupert Boch. Podobno zajmuje jeden z pokoi na górze w tawernie „Pod Szubienicą”, na południowo-wschodnim krańcu miasteczka.', 0),
(6742, 'koKR', 'Szukasz Ruperta Bocha. On i jego świta mają pokój na górze w tawernie „Pod Szubienicą”, na południowo-wschodnim krańcu Brill.', 'Szukasz Ruperta Bocha. On i jego świta mają pokój na górze w tawernie „Pod Szubienicą”, na południowo-wschodnim krańcu Brill.', 0),
(6743, 'koKR', 'Austila de Mon szukaj w głównej sali jadalnej tawerny „Pod Szubienicą”. Tawerna stoi na południowo-wschodnim skraju Brill.', 'Austila de Mon szukaj w głównej sali jadalnej tawerny „Pod Szubienicą”. Tawerna stoi na południowo-wschodnim skraju Brill.', 0),
(6744, 'koKR', 'Tak, to będzie Austil de Mon. Zawsze przesiaduje w tawernie na południowo-wschodnim krańcu miasteczka. Nazywa się „Pod Szubienicą”, nie przegapisz jej.', 'Tak, to będzie Austil de Mon. Zawsze przesiaduje w tawernie na południowo-wschodnim krańcu miasteczka. Nazywa się „Pod Szubienicą”, nie przegapisz jej.', 0),
(6745, 'koKR', 'Nasza alchemiczka nazywa się Carolai Anise. Znajdziesz ją w domu na północno-zachodnim krańcu Brill.', 'Nasza alchemiczka nazywa się Carolai Anise. Znajdziesz ją w domu na północno-zachodnim krańcu Brill.', 0),
(6746, 'koKR', 'Carolai Anise znajdziesz na północno-zachodnim krańcu miasteczka, gdzie próbuje wysadzić swój dom w powietrze. Może pójdziesz sprawdzić, czy da się jej pomóc?', 'Carolai Anise znajdziesz na północno-zachodnim krańcu miasteczka, gdzie próbuje wysadzić swój dom w powietrze. Może pójdziesz sprawdzić, czy da się jej pomóc?', 0),
(6747, 'koKR', 'Wybacz, przyjacielu, tu w Brill czegoś takiego nie mamy. Musisz się po to udać do Podmiasta. Podmiasto leży pod Ruinami Lordaeronu, na południe od Brill. Z tyłu ruin zjedź windą na dół, a potem zapytaj o dalszą drogę któregoś ze strażników Podmiasta.', 'Wybacz, przyjacielu, tu w Brill czegoś takiego nie mamy. Musisz się po to udać do Podmiasta. Podmiasto leży pod Ruinami Lordaeronu, na południe od Brill. Z tyłu ruin zjedź windą na dół, a potem zapytaj o dalszą drogę któregoś ze strażników Podmiasta.', 0),
(6748, 'koKR', 'Kowal? Nie ma. Nasz ostatni znów zmienił się w jednego z tych bezmyślnych sług Plagi. Ale jest jeden w Podmieście, na południe od miasteczka. Podmiasto leży pod Ruinami Lordaeronu – sprytna nazwa, co? Zjedź po prostu windą na tyłach ruin, a potem porozmawiaj z którymś ze strażników Podmiasta. Powinni wskazać ci właściwy kierunek.', 'Kowal? Nie ma. Nasz ostatni znów zmienił się w jednego z tych bezmyślnych sług Plagi. Ale jest jeden w Podmieście, na południe od miasteczka. Podmiasto leży pod Ruinami Lordaeronu – sprytna nazwa, co? Zjedź po prostu windą na tyłach ruin, a potem porozmawiaj z którymś ze strażników Podmiasta. Powinni wskazać ci właściwy kierunek.', 0),
(6749, 'koKR', 'Masz się za kucharza? Na naukę ruszaj do Podmiasta, na południe od miasteczka. Windy na dół znajdziesz na tyłach Ruin Lordaeronu. Gdy dotrzesz na miejsce, poproś o dalszą pomoc któregoś z tych ociężałych strażników Podmiasta.', 'Masz się za kucharza? Na naukę ruszaj do Podmiasta, na południe od miasteczka. Windy na dół znajdziesz na tyłach Ruin Lordaeronu. Gdy dotrzesz na miejsce, poproś o dalszą pomoc któregoś z tych ociężałych strażników Podmiasta.', 0),
(6750, 'koKR', 'Po co gotować, skoro wszystko smakuje w ustach jak popiół? O ile jeszcze masz usta. No dobrze, idź do Podmiasta na południe od Brill i zapytaj tamtejszego strażnika Podmiasta o drogę do nauczyciela gotowania. Na dół zjedziesz windą z tyłu Ruin Lordaeronu.', 'Po co gotować, skoro wszystko smakuje w ustach jak popiół? O ile jeszcze masz usta. No dobrze, idź do Podmiasta na południe od Brill i zapytaj tamtejszego strażnika Podmiasta o drogę do nauczyciela gotowania. Na dół zjedziesz windą z tyłu Ruin Lordaeronu.', 0),
(6751, 'koKR', 'Vance\'a Podmroka znajdziesz w pokoju na górze w tawernie „Pod Szubienicą”, po południowo-wschodniej stronie Brill.', 'Vance\'a Podmroka znajdziesz w pokoju na górze w tawernie „Pod Szubienicą”, po południowo-wschodniej stronie Brill.', 0),
(6752, 'koKR', 'Mówią, że Vance Podmrok wynajął na stałe pokój na górze w tawernie „Pod Szubienicą”, na południowo-wschodnim krańcu miasteczka. Chyba tuż obok czytelni.', 'Mówią, że Vance Podmrok wynajął na stałe pokój na górze w tawernie „Pod Szubienicą”, na południowo-wschodnim krańcu miasteczka. Chyba tuż obok czytelni.', 0),
(6753, 'koKR', 'W Brill nie ma nauczyciela inżynierii, ale jest jeden na dole, w Podmieście. Żeby tam trafić, idź na tyły Ruin Lordaeronu na południe od miasteczka i zjedź windą. Na miejscu zapytaj strażnika Podmiasta o dokładniejszą drogę.', 'W Brill nie ma nauczyciela inżynierii, ale jest jeden na dole, w Podmieście. Żeby tam trafić, idź na tyły Ruin Lordaeronu na południe od miasteczka i zjedź windą. Na miejscu zapytaj strażnika Podmiasta o dokładniejszą drogę.', 0),
(6754, 'koKR', 'Strzelby, dynamit, bomby, wybuchające owce... czego tu nie kochać? Żeby nauczyć się robić to i wiele innych ekscytujących narzędzi fachu, ruszaj do Podmiasta, pod Ruinami Lordaeronu na południe od Brill. Zjedź windą na tyłach ruin. Gdy dotrzesz, zapytaj któregoś ze strażników Podmiasta, gdzie dokładnie jest nauczyciel.', 'Strzelby, dynamit, bomby, wybuchające owce... czego tu nie kochać? Żeby nauczyć się robić to i wiele innych ekscytujących narzędzi fachu, ruszaj do Podmiasta, pod Ruinami Lordaeronu na południe od Brill. Zjedź windą na tyłach ruin. Gdy dotrzesz, zapytaj któregoś ze strażników Podmiasta, gdzie dokładnie jest nauczyciel.', 0),
(6755, 'koKR', 'Pielęgniarka Neela wita wszystkich swoich przyszłych klientów, gdy tylko wchodzą do tawerny „Pod Szubienicą” na południowo-wschodnim krańcu miasteczka.', 'Pielęgniarka Neela wita wszystkich swoich przyszłych klientów, gdy tylko wchodzą do tawerny „Pod Szubienicą” na południowo-wschodnim krańcu miasteczka.', 0),
(6756, 'koKR', 'Rzeźnik, mówisz? Ach, nauczyciel pierwszej pomocy! Na jedno wychodzi. Zrozumiesz, gdy zobaczysz pielęgniarkę Neelę, która stoi tuż za drzwiami tawerny „Pod Szubienicą”, po południowo-wschodniej stronie miasteczka.', 'Rzeźnik, mówisz? Ach, nauczyciel pierwszej pomocy! Na jedno wychodzi. Zrozumiesz, gdy zobaczysz pielęgniarkę Neelę, która stoi tuż za drzwiami tawerny „Pod Szubienicą”, po południowo-wschodniej stronie miasteczka.', 0),
(6757, 'koKR', 'Clyde Kellen, tutejszy mistrz połowu okoni, ma swoje ulubione łowisko tuż na wschód od Brill, nad Jeziorem Jasnym.', 'Clyde Kellen, tutejszy mistrz połowu okoni, ma swoje ulubione łowisko tuż na wschód od Brill, nad Jeziorem Jasnym.', 0),
(6758, 'koKR', 'Tak, Clyde\'a Kellena zawsze znajdziesz z wędką na brzegu Jeziora Jasnego, tuż na wschód od Brill. Tylko uważaj tam na świrów w maskach. W zeszłym roku musieliśmy zamknąć letni obóz dla dzieci.', 'Tak, Clyde\'a Kellena zawsze znajdziesz z wędką na brzegu Jeziora Jasnego, tuż na wschód od Brill. Tylko uważaj tam na świrów w maskach. W zeszłym roku musieliśmy zamknąć letni obóz dla dzieci.', 0),
(6759, 'koKR', 'Szukaj Faruzy. Ostatnio stała przed wejściem, między stajnią a domem na północno-zachodnim krańcu miasteczka.', 'Szukaj Faruzy. Ostatnio stała przed wejściem, między stajnią a domem na północno-zachodnim krańcu miasteczka.', 0),
(6760, 'koKR', 'Szczerze mówiąc, wolę tradycyjną medycynę... pijawki, czerwie, piły do kości... tego rodzaju rzeczy. Cóż, każdy ma swój gust. Naszą nauczycielkę ziołozbieractwa, Faruzę, znajdziesz przed wejściem, niedaleko stajni w Brill.', 'Szczerze mówiąc, wolę tradycyjną medycynę... pijawki, czerwie, piły do kości... tego rodzaju rzeczy. Cóż, każdy ma swój gust. Naszą nauczycielkę ziołozbieractwa, Faruzę, znajdziesz przed wejściem, niedaleko stajni w Brill.', 0),
(6761, 'koKR', 'To będzie Shelene Rhobart. Wyjdź z Brill drogą na południowy wschód, a na skrzyżowaniu skręć na wschód. Obozuje przy drodze.', 'To będzie Shelene Rhobart. Wyjdź z Brill drogą na południowy wschód, a na skrzyżowaniu skręć na wschód. Obozuje przy drodze.', 0),
(6762, 'koKR', 'Nie ma to jak dotyk czegoś martwego ocierającego się o ciebie. Shelene Rhobart znajdziesz, idąc drogą na południowy wschód z miasteczka, a potem na skrzyżowaniu na wschód. Ma tam mały obóz, niedaleko przy drodze.', 'Nie ma to jak dotyk czegoś martwego ocierającego się o ciebie. Shelene Rhobart znajdziesz, idąc drogą na południowy wschód z miasteczka, a potem na skrzyżowaniu na wschód. Ma tam mały obóz, niedaleko przy drodze.', 0),
(6763, 'koKR', 'Podobno w Podmieście jest nauczyciel górnictwa. Żeby tam trafić, wystarczy iść na południe z miasteczka, na tyły Ruin Lordaeronu. Potem zjedź windą do samego Podmiasta i zapytaj strażnika Podmiasta o dalszą drogę.', 'Podobno w Podmieście jest nauczyciel górnictwa. Żeby tam trafić, wystarczy iść na południe z miasteczka, na tyły Ruin Lordaeronu. Potem zjedź windą do samego Podmiasta i zapytaj strażnika Podmiasta o dalszą drogę.', 0),
(6764, 'koKR', 'Pewnie pierwszym ćwiczeniem będzie wykopanie sobie drogi do Podmiasta. He, łapiesz? Kopanie... nieważne. Do Podmiasta dojdziesz przez tyły Ruin Lordaeronu na południe od Brill; tam zjedź windą. Zapytaj o dalszą pomoc któregoś ze strażników Podmiasta.', 'Pewnie pierwszym ćwiczeniem będzie wykopanie sobie drogi do Podmiasta. He, łapiesz? Kopanie... nieważne. Do Podmiasta dojdziesz przez tyły Ruin Lordaeronu na południe od Brill; tam zjedź windą. Zapytaj o dalszą pomoc któregoś ze strażników Podmiasta.', 0),
(6765, 'koKR', 'Rand Rhobart całkiem nieźle obdziera ze skóry spaczone nietoperze i tym podobne. Znajdziesz go w obozie przy drodze na południowy wschód od Brill. Wyjdź z miasteczka drogą na południowy wschód, a na skrzyżowaniu skręć na wschód.', 'Rand Rhobart całkiem nieźle obdziera ze skóry spaczone nietoperze i tym podobne. Znajdziesz go w obozie przy drodze na południowy wschód od Brill. Wyjdź z miasteczka drogą na południowy wschód, a na skrzyżowaniu skręć na wschód.', 0),
(6766, 'koKR', 'Chcesz zostać wypychaczem zwierząt? Nie lubię ludzi, którzy myślą, że mogą mnie wypchać i powiesić na ścianie, bo uważają, że nie żyję. Nie? To dobrze! Szukaj Randa Rhobarta w obozie na południowy wschód od miasteczka. Żeby do niego trafić, wyjdź z Brill drogą na południowy wschód i na skrzyżowaniu skręć w lewo.', 'Chcesz zostać wypychaczem zwierząt? Nie lubię ludzi, którzy myślą, że mogą mnie wypchać i powiesić na ścianie, bo uważają, że nie żyję. Nie? To dobrze! Szukaj Randa Rhobarta w obozie na południowy wschód od miasteczka. Żeby do niego trafić, wyjdź z Brill drogą na południowy wschód i na skrzyżowaniu skręć w lewo.', 0),
(6767, 'koKR', 'W takim razie szukasz Bowena Brisboise\'a. Znajdziesz go w jego domu na południowy zachód od Brill, zaraz za mostem, w Dworze Zimnego Paleniska.', 'W takim razie szukasz Bowena Brisboise\'a. Znajdziesz go w jego domu na południowy zachód od Brill, zaraz za mostem, w Dworze Zimnego Paleniska.', 0),
(6768, 'koKR', 'Czerń, szarość i ciemny fiolet – oto obowiązujące barwy. Pilnuj się, przyjacielu, żeby nie zboczyć na złą stronę modowej ulicy. Bowen Brisboise pomoże ci tego uniknąć. Znajdziesz go we Dworze Zimnego Paleniska, za mostem na południowy zachód od miasteczka.', 'Czerń, szarość i ciemny fiolet – oto obowiązujące barwy. Pilnuj się, przyjacielu, żeby nie zboczyć na złą stronę modowej ulicy. Bowen Brisboise pomoże ci tego uniknąć. Znajdziesz go we Dworze Zimnego Paleniska, za mostem na południowy zachód od miasteczka.', 0),
(6790, 'koKR', 'Treser nietoperzy', 'Treser nietoperzy', 0),
(6869, 'koKR', 'Witaj, przyjacielu. Jestem oficer Garush i z dumą należę do ogólnoświatowej organizacji zwanej Krucjatą Argentu. Naszą sprawą jest walczyć szybko i bez litości z każdym przejawem zła, który pojawi się w Azeroth. Nie jesteśmy stronnictwem politycznym i nigdy nie chcemy nim zostać. Nasz cel jest jeden, dlatego i Hordę, i Przymierze nazywamy przyjaciółmi – przyjaciółmi w sprawie tępienia zła!$B$BZa Krucjatę, $gbracie:siostro;!', '', 0),
(6876, 'koKR', '', 'Argentowy Brzask pozdrawia cię, $N. Jestem Hasana – jedna z nielicznych upoważnionych kwatermistrzyń Brzasku od sprzętu i zaopatrzenia.$B$BGdy będziesz walczyć ze złem na nasze zlecenie – zdobywając przy tym nasz szacunek i zaufanie – otrzymasz od oficera Garusha żetony męstwa. Żetony służą dwóm celom: możesz nimi podnieść swoją pozycję w naszych szeregach albo płacić nimi za wyjątkowe przedmioty.$B$BIm lepszą pozycję zdobędziesz w Brzasku, tym więcej przedmiotów zostanie ci udostępnionych.', 0),
(7125, 'koKR', 'Witaj, $N. Mój obóz stoi tu, przy Barykadzie – tu przygotowuję się do wyprawy na Plagowiska. Doszły mnie słuchy, że niedawno w Żagiewiu zamieszkał wielki ludzki czarodziej. Szkarłatna Krucjata zleciła mu wykonanie nowych łuków i strzelb dla swoich wojowników i łowców. Podobno ukończył niezwykłą broń, zanim Krucjata go zabiła.$B$BWidać ich nieufność wobec magii jeszcze urosła.', '', 0),
(7128, 'koKR', '', 'Moja rodzina pracowała w Tartaku Północnego Grzbietu, na terenie dzisiejszych Zachodnich Plagowisk. Służyła wiernie rodowi Dumahów, a teraz Szkarłatna Krucjata zajęła tartak razem z całym Żagiewiem!$B$BNie spocznę, dopóki ci fanatycy nie znikną z powierzchni Azeroth.', 0),
(7278, 'koKR', 'Roztwór w moim kotle jest gotowy. Teraz wystarczy zanurzyć w nim i niedokończony klucz, i skarabeusza.', '', 0),
(7279, 'koKR', 'Gotowe, $n. Myślę, że wynik cię zadowoli.', '', 0),
(7280, 'koKR', 'Roztwór w moim kotle jest gotowy. Teraz wystarczy zanurzyć w nim i niedokończony klucz, i skarabeusza.', '', 0),
(7281, 'koKR', 'Gotowe, $n. Myślę, że wynik cię zadowoli.', '', 0),
(7498, 'koKR', 'Witaj, przyjacielu. Niech Brzask ma cię w opiece w tych niespokojnych czasach.', '', 0),
(7525, 'koKR', 'W imieniu Królewskich Zakładów Chemicznych mam przyjemność zaoferować ci najlepsze wierzchowce, jakie są dostępne dla Porzuconych. Te zwierzęta przeszły próby i udręki, jak my wszyscy, a teraz i one wyszły z nich silniejsze i bardziej wytrzymałe, niż pozwoliłoby im na to zwykłe śmiertelne ciało! Proszę, obejrzyj je i przekonaj się $gsam:sama;.', 'W imieniu Królewskich Zakładów Chemicznych mam przyjemność zaoferować ci najlepsze wierzchowce, jakie są dostępne dla Porzuconych. Te zwierzęta przeszły próby i udręki, jak my wszyscy, a teraz i one wyszły z nich silniejsze i bardziej wytrzymałe, niż pozwoliłoby im na to zwykłe śmiertelne ciało! Proszę, obejrzyj je i przekonaj się $gsam:sama;.', 0),
(7535, 'koKR', 'Mogę cię nauczyć tajników jazdy na szkieletowym koniu, o ile masz dość złota, by pokryć koszt lekcji!', 'Mogę cię nauczyć tajników jazdy na szkieletowym koniu, o ile masz dość złota, by pokryć koszt lekcji!', 0),
(7586, 'koKR', 'Żadna inna rasa w Azeroth nie wycierpiała tyle co nasz lud, $N. Śmiech w obliczu śmierci stał się dla nas wszystkich drugą naturą.', '', 0),
(7792, 'koKR', 'Dziękuję! Dziękuję, $gkapłanie:kapłanko;. Teraz, z twoją mocą za plecami, poradzę sobie z tymi gnollami!', '', 0),
(7793, 'koKR', 'Żegnaj i niech cień zawsze cię chroni!', '', 0),
(7922, 'koKR', 'Witaj, $gwędrowcze:wędrowczyni;! Chcesz zgłębić tajemnice magii? Hm?', '', 0),
(7964, 'koKR', '', 'Skóra, wspaniała skóra. Trzyma twoje wnętrzności... w środku. Pewnie $gzauważyłeś:zauważyłaś;, że moja skóra nie ma się najlepiej. Pomyśleć, że kiedyś martwiły mnie pory. Dziś ledwie zostało skóry, żeby się nią martwić. W pewnym sensie to bardzo wyzwalające.', 0),
(7979, 'koKR', 'POMOCY! ZABÓJCY PRZYSZLI MNIE ZAMORDOWAĆ!', '', 0),
(8077, 'koKR', 'Miło mi cię poznać. W czym mogę pomóc?', '', 0),
(8283, 'koKR', 'Za Hordę!', '', 0),
(8411, 'koKR', 'Królewskie Zakłady Chemiczne mają niewiele cierpliwości dla głupców, podobnie jak ja. Może gdy następnym razem porozmawiamy o moich wierzchowcach, będziesz mieć u Podmiasta reputację Wywyższony. Do tego czasu...', 'Królewskie Zakłady Chemiczne mają niewiele cierpliwości dla głupców, podobnie jak ja. Może gdy następnym razem porozmawiamy o moich wierzchowcach, będziesz mieć u Podmiasta reputację Wywyższony. Do tego czasu...', 0),
(8432, 'koKR', 'Zanim nauczę cię jazdy, musisz mieć u Porzuconych z Podmiasta reputację Wywyższony, $N.', 'Zanim nauczę cię jazdy, musisz mieć u Porzuconych z Podmiasta reputację Wywyższony, $N.', 0),
(8519, 'koKR', 'Stajennego Morganusa znajdziesz, o dziwo, przed stajnią.', 'Stajennego Morganusa znajdziesz, o dziwo, przed stajnią.', 0),
(8520, 'koKR', 'Nie grzeszysz bystrością, co? Hmm, gdzie też mógłby się kręcić stajenny? Może w pobliżu, powiedzmy, stajni? Szukaj tam Morganusa.', 'Nie grzeszysz bystrością, co? Hmm, gdzie też mógłby się kręcić stajenny? Może w pobliżu, powiedzmy, stajni? Szukaj tam Morganusa.', 0),
(11491, 'koKR', 'Gdzie jest Nestor Księżycowy Cios?', 'Gdzie jest Nestor Księżycowy Cios?', 0),
(11492, 'koKR', 'Nestor Księżycowy Cios przebywa w Scholomancjum na Zachodnich Plagowiskach.', 'Nestor Księżycowy Cios przebywa w Scholomancjum na Zachodnich Plagowiskach.', 0),
(11497, 'koKR', 'Gdzie jest Nestor Obsydian?', 'Gdzie jest Nestor Obsydian?', 0),
(11498, 'koKR', 'Nestor Obsydian przechadza się w pobliżu Grobowiska w Srebrzystym Borze.', 'Nestor Obsydian przechadza się w pobliżu Grobowiska w Srebrzystym Borze.', 0),
(11499, 'koKR', 'Gdzie jest Nestor Śnieżna Korona?', 'Gdzie jest Nestor Śnieżna Korona?', 0),
(11500, 'koKR', 'Nestor Śnieżna Korona przebywa w Kaplicy Świetlistej Nadziei na Wschodnich Plagowiskach.', 'Nestor Śnieżna Korona przebywa w Kaplicy Świetlistej Nadziei na Wschodnich Plagowiskach.', 0),
(11653, 'koKR', 'Gdzie jest Nestor Łąkobieg?', 'Gdzie jest Nestor Łąkobieg?', 0),
(11654, 'koKR', 'O ile wiem, Nestor Łąkobieg przebywa przy Płaczącej Jaskini na Zachodnich Plagowiskach.', 'O ile wiem, Nestor Łąkobieg przebywa przy Płaczącej Jaskini na Zachodnich Plagowiskach.', 0),
(11679, 'koKR', 'Nic tak nie rozgrzewa kości jak odrobina księżycowego świętowania!', 'Nic tak nie rozgrzewa kości jak odrobina księżycowego świętowania!', 0),
(11680, 'koKR', 'Trzeba uważać przy odpalaniu fajerwerków, kiedy nie czuje się palców...', 'Trzeba uważać przy odpalaniu fajerwerków, kiedy nie czuje się palców...', 0),
(11681, 'koKR', 'Ten promień księżycowego światła prowadzi do Podmiasta. Wróć, kiedy zechcesz.', 'Ten promień księżycowego światła prowadzi do Podmiasta. Wróć, kiedy zechcesz.', 0),
(12821, 'koKR', 'NAPRZÓD!', 'NAPRZÓD!', 0),
(13567, 'koKR', 'JESZCZE się zemszczę!', '', 0),
(13820, 'koKR', 'Co to ma być?', 'Co to ma być?', 0),
(14112, 'koKR', 'Uther Światłodzierżca przyniósł Quel\'Thalas tylko ciemność. Zobaczmy, czy zdołamy przynieść trochę ciemności do jego grobowca!', '', 0),
(14115, 'koKR', 'Nareszcie się zemszczę!', '', 0),
(18114, 'koKR', 'Zostaw mnie, $N. Muszę pełnić obowiązki przy ambasadorze Żalu Słońca, jakkolwiek nudne by były.', 'Zostaw mnie, $N. Muszę pełnić obowiązki przy ambasadorze Żalu Słońca, jakkolwiek nudne by były.', 0),
(18365, 'koKR', 'Paladyn? $gNałykałeś:Nałykałaś; się mikstur aptekarzy czy czegoś w tym rodzaju? Chodzą słuchy, że Mroczną Panią w Podmieście odwiedza jakaś elfia delegacja. Może ktoś z nich będzie wiedział.', 'Paladyn? $gNałykałeś:Nałykałaś; się mikstur aptekarzy czy czegoś w tym rodzaju? Chodzą słuchy, że Mroczną Panią w Podmieście odwiedza jakaś elfia delegacja. Może ktoś z nich będzie wiedział.', 0),
(22080, 'koKR', 'Odlatuje sterowiec do Orgrimmaru. Oby tym razem obyło się bez wybuchów.', 'Odlatuje sterowiec do Orgrimmaru. Oby tym razem obyło się bez wybuchów.', 0),
(22093, 'koKR', 'Sterowiec powinien był właśnie przylecieć do Grom\'gol.', 'Sterowiec powinien był właśnie przylecieć do Grom\'gol.', 0),
(22094, 'koKR', 'Sterowiec powinien był właśnie odlecieć z Grom\'gol.', 'Sterowiec powinien był właśnie odlecieć z Grom\'gol.', 0),
(22095, 'koKR', 'Sterowiec powinien był właśnie odlecieć z Podmiasta.', 'Sterowiec powinien był właśnie odlecieć z Podmiasta.', 0),
(23357, 'koKR', 'Za Hordę!', 'Za Hordę!', 0),
(25771, 'koKR', '', 'Północna Grań czeka, $N. Majestatyczny „Chmurocałus” zabierze cię prosto przez morze do Przystani Zemsty w Wyjącym Fiordzie.', 0),
(29540, 'koKR', 'Sterowiec do Przystani Zemsty właśnie przyleciał! Wszyscy na pokład, kierunek Wyjący Fiord!', 'Sterowiec do Przystani Zemsty właśnie przyleciał! Wszyscy na pokład, kierunek Wyjący Fiord!', 0),
(29551, 'koKR', 'Sterowiec do Orgrimmaru właśnie przyleciał! Wszyscy na pokład, kierunek Durotar!', 'Sterowiec do Orgrimmaru właśnie przyleciał! Wszyscy na pokład, kierunek Durotar!', 0),
(32266, 'koKR', 'Ten nędznik Putress nie ujdzie z tym na sucho!', 'Ten nędznik Putress nie ujdzie z tym na sucho!', 0),
(32330, 'koKR', 'Prędzej spalimy to do gołej ziemi, niż wam oddamy!', 'Prędzej spalimy to do gołej ziemi, niż wam oddamy!', 0),
(32339, 'koKR', 'BOHATEROWIE HORDY, WZYWA WAS WÓDZ!', '', 0),
(32340, 'koKR', 'Na krew i grom, czempioni Hordy! Walczymy dziś za naszych poległych braci i siostry! Nie opłakujcie ich, bo wszyscy zginęli z honorem w sercach!', '', 0),
(32341, 'koKR', 'Choć czeka nas ciężka walka, nasza połączona potęga zmiażdży tych, którzy staną nam na drodze! Za straszliwe krzywdy wyrządzone Hordzie spadnie na nich niepowstrzymana siła odwetu!', '', 0),
(32342, 'koKR', 'Wzywam was, wielkie duchy! Pobłogosławcie Hordę! Bo tego dnia nasza sprawa jest słuszna i sprawiedliwa!', '', 0),
(32361, 'koKR', 'Zbierzcie się za mną u bram Podmiasta! Wkrótce ruszymy na nasze upadłe miasto i odbijemy je – ZA HORDĘ!', '', 0),
(32362, 'koKR', 'Duchy wiatru, zanieście Zaurzykłowi Młodszemu pieśń wojny! Niech WSZYSCY nasi polegli bracia zostaną w tej bitwie pomszczeni!\n', '', 0),
(32363, 'koKR', 'Bitwa o Podmiasto zaczyna się teraz! Dąć w rogi wojenne! Czempioni Hordy, niech wzmocni was potęga waszego wodza!', '', 0),
(32366, 'koKR', 'NAPRZÓD!', '', 0),
(32367, 'koKR', 'Wielki bracie wietrze, oczyść nam drogę!', '', 0),
(32368, 'koKR', 'Odpowiesz przed żywiołami, demonie!', '', 0),
(32369, 'koKR', 'Wielki duchu wody, zmyj to skażenie!', '', 0),
(32396, 'koKR', 'DO ATAKU!!!!', '', 0),
(32460, 'koKR', 'Dziedziniec jest nasz! Naprzód, do wewnętrznego sanktuarium!', '', 0),
(32461, 'koKR', 'STAĆ! Zniszczyli windę!', '', 0),
(32462, 'koKR', '', 'Szyb jest najeżony pułapkami, wodzu. Skok oznaczałby pewną śmierć.', 0),
(32489, 'koKR', '', 'Co oni zrobili z moim pięknym miastem!', 0),
(32490, 'koKR', 'Wielki duchu powietrza, usłysz raz jeszcze moje wezwanie!', '', 0),
(32491, 'koKR', 'Duchy powietrza usłyszały moje wezwanie. Cyklony bezpiecznie nas opuszczą. Teraz skaczemy!', '', 0),
(32494, 'koKR', 'Wdarliśmy się do wewnętrznego sanktuarium, bohaterowie! Przemy naprzód!', '', 0),
(32495, 'koKR', '', 'Jedynym odkupieniem dla zdrajców, którzy za to odpowiadają, będzie śmierć w męczarniach. Moja zemsta będzie szybka i bezlitosna.', 0),
(32496, 'koKR', 'Prowadź, Mroczna Pani. Pójdziemy za tobą.', '', 0),
(32497, 'koKR', '', 'Dobrze, wodzu. Królewski Kwartał jest tędy. Miejcie się na baczności. Nie wiadomo, co szykują dla nas Varimathras i Putress.', 0),
(32520, 'koKR', '', 'STAĆ! Wyczuwam mroczną magię. Demoniczną magię... Przygotujcie się!', 0),
(32553, 'koKR', 'To wszystko, demonie? Nie masz już nic, czym mógłbyś w nas cisnąć?', '', 0),
(32564, 'koKR', 'Idziemy po ciebie! Szykuj się!', '', 0),
(32565, 'koKR', 'TCHÓRZU! Myślisz, że zatrzymasz wodza Hordy kamyczkami? Pokażę ci prawdziwą potęgę żywiołów!', '', 0),
(32567, 'koKR', '', 'Królewski Kwartał jest tuż przed nami, wodzu.', 0),
(32575, 'koKR', 'Wielkie duchy ziemi, pomóżcie nam w godzinie potrzeby!', '', 0),
(32583, 'koKR', 'RUSZAMY! SZYBKO!', '', 0),
(32584, 'koKR', 'Co to ma być?', '', 0),
(32643, 'koKR', 'ZWYCIĘŻYLIŚMY!', '', 0),
(32644, 'koKR', 'Podmiasto znów należy do Hordy! LOK\'TAR!', '', 0),
(32646, 'koKR', 'Mroczna Pani, dołącz do mnie! Ciężko walczyłaś i przelałaś wiele krwi, by zdobyć to prawo. Królewski Kwartał należy do ciebie!', '', 0),
(32647, 'koKR', '', 'Taki los spotka wszystkich wrogów Hordy, wodzu. Teraz musimy rozprawić się z tym nędznikiem, Putressem.', 0),
(32648, 'koKR', 'Rozprawimy się, Sylwano...', '', 0),
(32649, 'koKR', 'Rogi Przymierza? Miejcie się na baczności!', '', 0),
(32728, 'koKR', 'Kończy się tak, jak się zaczęło...', '', 0),
(32729, 'koKR', 'Wszystko, o co walczyliśmy na tym świecie, przepadło. Nadzieje i marzenia mojego ojca i matki... Zgładziciela... Przepadły...', '', 0),
(32730, 'koKR', 'Gdybyś tylko był tu teraz, stary przyjacielu. Wiedziałbyś, co robić.', '', 0),
(32735, 'koKR', 'Dobrze, że wróciłeś, Varoku, stary przyjacielu. Przykro mi z powodu twojego syna.', '', 0),
(34024, 'koKR', 'Upadek Lordaeronu zastał mnie tutaj, w odwiedzinach u krewnych, a potem... cóż. Chyba już nigdy nie wrócę do Zachodniego Skraju.$B$BCzasem zastanawiam się, czy moja rodzina jeszcze żyje. Częściej jednak zastanawiam się, dlaczego już mnie to nie obchodzi.', '', 0),
(36516, 'koKR', 'Szukaj w Podmieście. W starych Ruinach Lordaeronu, na południe stąd, znajdziesz windę na dół. Na miejscu zapytaj strażnika Podmiasta o dalszą drogę.', 'Szukaj w Podmieście. W starych Ruinach Lordaeronu, na południe stąd, znajdziesz windę na dół. Na miejscu zapytaj strażnika Podmiasta o dalszą drogę.', 0),
(39113, 'koKR', '<Strażnik śmierci Simmer patrzy na ciebie wyczekująco.>', '', 0),
(39129, 'koKR', 'Wybierasz się gdzieś?', '', 0),
(39172, 'koKR', 'Simmer mówić, Gordo mieć dużo w brzuchu, ale nic w głowie. Czemu on taki wredny?', '', 0),
(39173, 'koKR', 'Gordo lubić zrywać kwiatki. Zrywać kwiatki to trochę jak zabijać.', '', 0),
(39174, 'koKR', 'Tu być przeciąg.', '', 0),
(39175, 'koKR', 'Johaan mówić, Gordo potrzebować krawiec, żeby zaszyć Gordo brzuch.', '', 0),
(44545, 'koKR', 'Widać los zawsze mi sprzyjał, $n. Wrócić na świat w szeregach Porzuconych i Zakładów Chemicznych... lepszego przeznaczenia nie mogło mi się trafić.', '', 0);
